// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":36,"question":"سائل يقول: فضيلة الشيخ/ عبد العزيز.السلام عليكم ورحمة الله وبركاته.أما بعد: إنني أحبك حبًا شديدًا، حبًا في الله؛ لما قدمته لنا من الخير والفضل الذي تقدمه إلينا دائمًا في كل وقت.وبعد: كانت عائلتي صغيرة، وكنا نقطن في قرية صغيرة، وكان قد أصابنا جوع وقحط، وكانت أمي تأخذ من عند أهلها حبًّا بدون علمهم ولا دراية منهم، فتطحنه وتقدمه لنا غذاءً، نريد من فضيلة الشيخ أن يفيدنا فيما يجب على الوالدة أن تفعله، وما هي الكفارة إذا كان علينا شيء؟ أفيدونا أثابكم الله!","title":"حكم من تأخذ من بيت أهلها طعامًا لأولادها","answer":"الجواب: أما حبك لأخيك في الله، فأقول: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم من المتحابين بجلاله، فقد قال عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي، ويقول ﷺ: سبعة يظلهم الله في ظله - وذَكَر منهم - المتحابين في الله.\nوأما ما يتعلق بما فعلته أمك في حال الجوع والحاجة مما تأخذ من بيت أهلها: فلا حرج عليها في ذلك؛ لأن الواجب على أهلها من أبيها وأمها أن يطعموها وأن يطعموا أولادها إذا كان ليس لهم من يعينهم، ولا من ينفق عليهم، فالواجب عليهم أن ينفقوا ويحسنوا إليهم، والمسلمون شيء واحد، يجب عليهم أن يرحموا فقيرهم ويواسوه، ويحسنوا إليه، ويقوموا بحاجته، فالمسلم أخو المسلم.\nوفي الصحيحين عن ابن عمر رضي الله تعالى عنهما، قال: قال رسول الله ﷺ: المسلم أخو المسلم، لا يظلمه ولا يُسلمه -أي: لا يخذله ويتركه لمن يظلمه- ومن كان في حاجة أخيه كان الله في حاجته.\nوقالت هند بنت عتبة: يا رسول الله! إن أبا سفيان رجل شحيح، لا يعطيني ما يكفيني ويكفي بَنِيَّ إلا ما أخذتُ من ماله بغير علم، فهل علي في هذا من جناح؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك أي: بغير علم.\nفما أخذته أمك من أهلها من بيت أبيها وأمها مما يسبب إنقاذها وإنقاذ أولادها، لا حرج فيه، ولا شيء عليها فيه ما دامت محتاجة، وليس هناك من يقوم بها غيرهم.","link":"https://binbaz.org.sa/fatwas/2816/حكم-من-تاخذ-من-بيت-اهلها-طعاما-لاولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0009.mp3","categories":["النفقات"]},{"id":308,"question":"إذا كانت له عدّة زوجات، وإحدى هذه الزوجات لها أربعة من الأبناء، والأخرى لها ستة، هل يُساوي بينهما في النَّفقة أم هو مُخَيَّر؟","title":"هل تختلف نفقة الزوجات حسب عدد الأولاد؟","answer":"الجواب: لا، كل واحدةٍ تُعطى نفقتها التي تليق بها، التي عندها أربعة أولاد لها شأنٌ، والتي عندها ستة لها شأنٌ، والتي عندها ثمانية لها شأنٌ، كل واحدةٍ تُعطى ما يُناسبها مع أولادها، وليسوا على حدٍّ سواء؛ من أجل كثرة الأولاد وقلَّة الأولاد.\nأما الزوجة نفسها فتُعامل مثل الزوجة الأخرى التي عنده، فيعدل بين الاثنتين، وبعض أهل العلم قال: يُراعى في كل واحدةٍ حال عُرف أهلها وأُسرتها، ولكن ليس بظاهرٍ، بل الواجب أن يُراعي أن يعدل بينهن في الرزق والكسوة والقسمة مطلقًا، سواء كانت واحدةً من بنت الأغنياء، والثانية بنت الفقراء، الواجب أن يعدل بينهنَّ، سواء في النَّفقة والكُسوة والسَّكن والقسمة، نعم.","link":"https://binbaz.org.sa/fatwas/4311/هل-تختلف-نفقة-الزوجات-حسب-عدد-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0358.mp3","categories":["النفقات"]},{"id":460,"question":"أخذ المرأة من مال زوجها؛ لأجل حاجتها، يشترط إذن الزوج؟","title":"هل يجوز أخذ المرأة من مال زوجها لحاجتها؟","answer":"الجواب: لا، لحاجتها ما يشترط، قالت هند: يا رسول الله، إن أبا سفيان رجل شحيح ما يعطينا ما يكفينا ويكفي بنيّ إلا ما أخذته من ماله بغير علمه، فهل عليّ من جناح؟ فقال ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك بغير إذنه.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6185/هل-يجوز-اخذ-المراة-من-مال-زوجها-لحاجتها","audio":"https://files.zadapps.info/binbaz.org.sa/mal020.mp3","categories":["النفقات"]},{"id":461,"question":"بعض النسوة إذا أعطاها زوجها مالاً للمصاريف فتأخذ من هذا المال شيئًا فشيئًا حتى تجمع ويكون مالاً كثيرًا فتشتري منه الذهب من غير إذن زوجها ومن غير علم زوجها؟","title":"حكم أخذ الزوجة من النفقة المخصصة للبيت","answer":"الجواب: ما يجوز هذا، اللي يعطيها زوجها للنفقة يبقى للنفقة، ما تأخذ للذهب ونحوه.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6186/حكم-اخذ-الزوجة-من-النفقة-المخصصة-للبيت","audio":"https://files.zadapps.info/binbaz.org.sa/neswa021.mp3","categories":["النفقات"]},{"id":1563,"question":"أحد الرجال يأتي بالضروريات لزوجته، ولكن غير الضروريات لا يأتي بها؛ لأنه يريد جمع الأموال للزواج بأخرى، فهل له ذلك؟","title":"ما الذي تشمله النفقة على الزوجة بالمعروف؟","answer":"الجواب:\nإذا تصالحوا لا بأس، أو إذا سمحت زوجته، وإلا فالواجب أن يُعطيها النفقة بالمعروف، المتعارف بين أهل بلده.\nس: إذا كانت عندها ملابس ولكن تُطالبه بأن يأتي لها كل سنةٍ بملبس؟\nج: ما هو ملزوم، إذا كان عندها ما يكفي فما هو ملزوم.\nس: ما المقصود بـ ودِينَارٌ يُنْفِقُهُ علَى أَصْحابه في سبِيلِ اللَّهِ؟\nج: الذين معه في سبيل الله، يعني: المجاهدين المحتاجين، فيُعطيهم، فهذا له فضلٌ عظيمٌ، لكن بعد أهله، فأهله مقدَّمون.\nس: عليه كسوة؟\nج: بالمعروف، حسب المعروف.\nس: كل سنة واحدة؟\nج: لا، حسب المعروف، حسب بلاده وعرف بلاده وعرف جماعته؛ لأن الرسول ﷺ ما قدَّرها، والله ما قدَّرها، قال الله جل وعلا: وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233] المعروف يعني: المتعارف بين جماعته وأهل بلده، أهل الرياض مثلًا لهم حال، وأهل المدينة لهم حال، وأهل أبها لهم حال، وأهل الإحساء لهم حال، لهم أعراف بينهم.\nس: ألا يُعتبر قوله ﷺ: تُطْعِمَها إذا طَعِمتَ وتَكْسوها إذا اكتسَيتَ ضابطًا؟\nج: هذا من جهة القدرة.","link":"https://binbaz.org.sa/fatwas/21665/ما-الذي-تشمله-النفقة-على-الزوجة-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في النفقة على الزوجة.mp3","categories":["النفقات"]},{"id":1573,"question":"النفقة على العيال: الواجبات أم الكماليات؟","title":"ما ضابط النفقة الواجبة على العيال؟","answer":"الجواب:\nالإنفاق في الواجبات، بحيث لا يكون فيها إسراف ولا تبذير، الوسط.","link":"https://binbaz.org.sa/fatwas/21676/ما-ضابط-النفقة-الواجبة-على-العيال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النفقة على العيال.mp3","categories":["النفقات"]},{"id":1576,"question":"هل تُشترط النية في النفقة أو الاحتساب؟","title":"هل تُشترط النية والاحتساب في النفقة؟","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21679/هل-تشترط-النية-والاحتساب-في-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النية في النفقة أو الاحتساب.mp3","categories":["النفقات"]},{"id":2166,"question":"قولكم فيما سبق: البخل فيما يجب عليه مُحرَّم، وإذا لم يكن واجبًا عليه فهو مكروهٌ، فما معنى هذا؟","title":"حكم مَن يبخل بما يجب عليه","answer":"الجواب:\nكونه يبخل عمَّن يجب عليه هذا ما يجوز له، فكونه يبخل عمَّن تحته من أولاده وزوجته، ولا يُعطيهم كفايتهم؛ هذا ما يجوز، فيجب عليه أن يُنفق عليهم كفايتهم. أمَّا كونه يُنفق على الناس الآخرين فهذا مستحبٌّ، ولا يلزمه إلا الزكاة، فهي واجبة.\nس: ومعنى: مكروه؟\nج: إذا بخل وكانت عنده سعة والناس محاويج؛ فهو مكروه.","link":"https://binbaz.org.sa/fatwas/22287/حكم-من-يبخل-بما-يجب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البخل فيما يجب عليه.mp3","categories":["النفقات"]},{"id":2337,"question":"شخصٌ يقول أن أباه يأتي دائمًا بأموالٍ من القِمار؟","title":"حكم نفقات مَنْ مالُ والده من القمار؟","answer":"الجواب:\nينصحه ويُبيِّن له أنها حرام، وأنها مَيْسِر.\nس: يسأل عن النَّفقات: الأكل والشّرب؟\nج: لا يأكل منها إذا علم أنها مَيْسِر.\nس: علمًا بأنَّ ما عندهم إلا هذا؟\nج: ولو، يسأل الناسَ إذا اضْطُرَّ ولا يأكل الحرام.","link":"https://binbaz.org.sa/fatwas/22461/حكم-نفقات-من-مال-والده-من-القمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مال والده من القمار فما حكم النفقات منه.mp3","categories":["النفقات"]},{"id":3053,"question":"في قَبْض النفقة: يُؤخذ بقول الزوجة وإلا قول الزوج؟","title":"مَنْ يُؤخذ بقوله من الزوجين في قبض النفقة؟","answer":"الجواب: يُوكَل إلى أمرها، ما دام اسْتَفْتَت فالعهدة عليها، ما يُقال: هاتي البينة، يُبيّن لها الحكم والعُهدة عليها، لو قال... بالبيّنة؛ عَظُم الأمرُ واشتد.","link":"https://binbaz.org.sa/fatwas/23213/من-يوخذ-بقوله-من-الزوجين-في-قبض-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤخذ بقول الزوجة أو قول الزوج في النفقة.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":4029,"question":"هل على المرء حق في ماله غير الزكاة المفروضة؟","title":"هل في المال حق غير الزكاة؟","answer":"الجواب: نعم حقوق، ما هو حق واحد، نفقة الضيف، ونفقة الأولاد، ونفقة الزوجة، ونفقة الأقارب، ونفقة المضطر.","link":"https://binbaz.org.sa/fatwas/24265/هل-في-المال-حق-غير-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل على المرء حق في ماله غير الزكاة.mp3","categories":["النفقات"]},{"id":4222,"question":"إذا أنفق الرجل المسلم على أهله نفقة ولم يحتسبها هل تكون له صدقة؟","title":"هل يؤجر الرجل في نفقة أهله إذا لم يحتسبها؟","answer":"الجواب: يرجى له الخير؛ لأن في بعض الروايات عدم القيد نفقة الرجل على أهله صدقة، لكن إذا احتسبها يكون أكمل وأفضل.","link":"https://binbaz.org.sa/fatwas/24489/هل-يوجر-الرجل-في-نفقة-اهله-اذا-لم-يحتسبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نفقة الرجل على أهله صدقة.mp3","categories":["النفقات"]},{"id":4226,"question":"الإنفاق لا ينتقل من الإنفاق المالي إذا لم يجد شيئًا، لا مال ولا غيره؟","title":"ماذا يفعل من لا يجد مالًا أو شيئا ينفقه؟","answer":"الجواب: يدعو، يقول خيرًا، يقول النبي ﷺ: ما منكم من أحد إلا سيكلمه ربه، ليس بينه وبينه ترجمان، فينظر عن يمينه فلا يرى إلا ما قدّم، وينظر عن شماله فلا يرى إلا ما قدّم، وينظر تلقاء وجهه فلا يرى إلا النار، فاتقوا النار ولو بشق تمرة، فمن لم يجد فبكلمة طيبة رواه البخاري ومسلم في الصحيحين عن عدي بن حاتم، فمن لم يجد فبكلمة طيبة: أغناك الله، يسر الله أمرك، وما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/24493/ماذا-يفعل-من-لا-يجد-مالا-او-شيىا-ينفقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الإنفاق.mp3","categories":["النفقات"]},{"id":5015,"question":"هذا رجلٌ له ابنٌ مُتَخَلِّفٌ عقليًّا، وله بنتٌ، ولهم مالٌ يأتي إليهم من الشّؤون، يقول: وقطعوني الآن، وأسكن في بيتٍ وحدي، فهل تجب عليَّ النَّفقة على ابني اللَّذين قطعاني الآن؟","title":"حكم النفقة على القريب المحتاج","answer":"الجواب: إذا كانت عنده قدرة يُنفق عليهم من ماله، على ولده، وعلى بنته، إذا كانت المساعدةُ الحكوميةُ ما تكفيهم.\nس: إذا كانت ما تكفيهم؟\nج: يجب عليه أن يُنفق عليهم، فيجب الإنفاق على: الأب، والأم، والجد، والجدة، والأخ، فالأقارب يجب أن يُنفق بعضُهم على بعضٍ عند الحاجة، وهذا من صلة الرحم.\nس: وإذا كانت تكفيهم؟\nج: إذا كانت تكفيهم يُنْفِق على المحتاج منهم، وهو الولد.\nس: هما ابناه: ولده وبنته، ويقول: تأتيهما من الشؤون الاجتماعية أموال، وقد قطعاني الآن، فلا يصلاني، ولا يُسلِّمون عليَّ؟\nج: عياله؟\nس: نعم.\nج: عاقّون، عليهم إثم العقوق.\nس: والنَّفقة؟\nج: وأيش فيها؟\nس: يُنفق أو لا يُنفق؟\nج: هم فقراء؟\nس: هم يأتيهم شيءٌ من الشّؤون.\nج: إذا كان يكفيهم فلا، أمَّا إذا لم يكن يكفيهم فعليه أن يُنفق عليهم، ولو قطعوه: ليس الواصِلُ بالمُكافئ، ولكن الواصل الذي إذا قَطعت رحمُه وصلَها رواه البخاري في \"الصحيح\".","link":"https://binbaz.org.sa/fatwas/28827/حكم-النفقة-على-القريب-المحتاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النفقة على القريب المحتاج؟.mp3","categories":["النفقات"]},{"id":5057,"question":"إذا خرجت من غير إذنه؟","title":"ما المشروع لمن خرجت زوجته بغير إذنه؟","answer":"الجواب: يُوجِّهها ويُعلمها، فإذا كان خروجها فيه مصلحة -كعيادة مريض أو زيارةٍ لأهلها- فلا يُشدّد في الأمور، وإذا  كان خروجها يرتاب فيه يمنعها منه. \nأما إذا كان خروجًا مشروعًا وله وجهٌ فينبغي له ألا يُشدّد، فبعض الناس عنده تشدد وسوء ظن دائمًا، فإذا كانت المرأة صالحةً لا ينبغي أن يُساء الظنّ بها، وإذا كان خروجها خروجًا مشروعًا لأهلها في وقتٍ مناسبٍ، أو لجيرانها في وقتٍ مناسبٍ؛ لا حرج.","link":"https://binbaz.org.sa/fatwas/29320/ما-المشروع-لمن-خرجت-زوجته-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المشروع لمن خرجت زوجته بغير إذنه؟.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":5917,"question":"المرأة لا تحب زوجها، وهو كذلك كما تقول، فهي تسأل هل يلزم الشرع الزوج أن يصرف عليها، وعلى ولديها منه بعد الطلاق ببيت مستقل، أم لا؟","title":"النفقة على الأولاد بعد طلاق أمهم","answer":"الجواب: إذا تفارقا فعليهما أن يصطلحا على مسألة الأولاد في النفقة، ينظر حالهما في المحكمة، يصطلحا مع وليها معها في النفقة المطلوبة كل شهر، والحمد لله؛ فإن تنازعا يرجعا إلى المحكمة، المحكمة تنظر، وتقدر النفقة اللازمة، لكن الأولى من ذلك الصلح، الأولى من المحكمة الصلح، يصطلحان على نفقة مناسبة ينفقها على أولاده إذا كان طلقها، وعندها أولاد، هذا هو الأولى، فإن تنازعا؛  فيرجعا إلى  المحكمة، ما يمكن غير المحكمة تنظر في هذا.","link":"https://binbaz.org.sa/fatwas/1283/النفقة-على-الاولاد-بعد-طلاق-امهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_270.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":6736,"question":"من المعلوم أن العدل بين الأولاد في الأعطية واجب، ولكن قد يحتاج أحدهم ما لا يحتاج الآخر، فالكبير يحتاج مصاريف أكثر من الصغير، والبنت قد تحتاج بعض الذهب، فكيف يكون العدل بينهم؟","title":"كيفية العدل بين الأولاد في العطية والنفقة","answer":"الجواب: الأعطية التي فيها العدل، المنحة الزائدة على النفقة، الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم يعني في العطايا الزائدة، أما الإنفاق عليهم، فكل ينفق عليه بقدر حاجته، الكبير له نفقة، والرضيع له نفقة،  والذي بين هذين له نفقة، فليسوا سواء، فهذه نفقة واجبة، ينفق عليهم بقدر حاجتهم، فالكبير بحاجة إلى ملابس غير ملابس الصغير، في حاجة إلى الزواج، إذا كان ما عنده مال؛ يزوجه، بحاجة إلى السكن، والصغير حاجته دون [ذلك] فكل من الأولاد يعطى حاجته على حسب حاله، ولا .. تعديل، التعديل في ذلك أنه يعطى حاجته هذا التعديل. أما العطايا الزائدة على النفقة، هذا هو محل التعديل، ولا يخص أحدًا بشيء، فيعطي هذا .. وهذا ما يعطيه، هذا يعطيه سيارة، وهذا ما يعطيه سيارة، لا، يساوي بينهم، لكن في نفقتهم في الملابس، والمآكل، والمشارب، والسفر، ونحو ذلك، كل له قدر حاجته.","link":"https://binbaz.org.sa/fatwas/2607/كيفية-العدل-بين-الاولاد-في-العطية-والنفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1103.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":7006,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7016,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7118,"question":"والدي يملك أموالًا وعقارات، وله ثلاث زوجات، وقام بتزويجي أنا وأخي الذي يصغرني في السن، وكنا ولازلنا نسكن مع والدنا، وأصبحنا نملك الأولاد، عندها قال والدي: كل واحد يأخذ قطعة أرض، ويبنيها بقرض من الدولة، وقد ذهب والدي وإخوتي إلى المحكمة لإفراغ الأرض بأسمائنا، ولكنهم فوجئوا برفض القاضي حيث قال: إن هناك لهم إخوة كثيرون، وهم صغار من بنين وبنات، ولا بد أن يعطى كل واحد منهم قطعة أرض، أو يمنعوا جميعًا، علمًا بأني أعمل بوظيفة ودخلي لا يمكنني من شراء أرض، ما هو الحكم إذا أنا أعطيت والدي قطعتين أرض قد منحت لي من قبل الدولة في مكانين مختلفين من المملكة مقابل أن يفرغ لي أحد الأراضي التي في الرياض، على أن لدي شعور على أن الوالد إذا فعل بي هذا الشيء؛ فهو من أجل أن يمكنني الأرض التي في الرياض؟","title":"حكم عطية الوالد بعض أولاده دون الآخرين","answer":"الجواب:\n\nالذي قاله القاضي صواب، لأن الرسول  قال: اتقوا الله واعدلوا بين أولادكم فليس له أن يعطي بعض الأولاد أراضي، ولا يعطي الآخرين، فعليه أن يعمهم جميعًا، أو يتركهم جميعًا، هكذا أمر النبي ﷺ: اتقوا الله واعدلوا بين أولادكم.\n\nفإذا كان يريد نفعكم؛ يبيع عليكم بيعًا، يبيع عليكم الأراضي بيعًا، مثل ما يبيع على الناس من غير محاباة، يبيع عليكم الأرض بما تساوي عند أهل الخبرة بيعًا عليكم مؤجلًا، مثل ما يباع على الأجانب، يباع عليكم وتكون في ذمتكم؛ حتى يتيسر لكم الوفاء مثل ما يبيع على أناس أجانب.\n\nوإذا باعها عليكم بيعًا بأراضي أخرى من غير محاباة، بل بأراضي تكون قيمتها معادلة لقيمة الأرض التي أعطاكم بغير محاباة، ولا حيلة، فلا بأس بذلك؛ لأنه يجوز أن يبيع عليكم كما يبيع على غيركم.\n\nالسؤال: وإذا كانوا راضين؟\n\nالجواب: إن كانوا كبارًا، وراضين؛ لا بأس، أما إن كانوا صغارًا ما لهم رضا، إن كانوا مرشدين، ووافقوا مثل عنده عشرة أو ثمانية، وأعطى اثنين أو ثلاثة، ورضي الباقون، وهم مرشدون؛ لا بأس، أما إن كانوا صغارًا، أو مجانين، أو معتوهين ليس له ذلك.","link":"https://binbaz.org.sa/fatwas/3147/حكم-عطية-الوالد-بعض-اولاده-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1505.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":8303,"question":"هذه رسالة من المرسل محمد إمام حسن مصري يعمل بمنطقة الجوف، خلاصة رسالته أنه يقول بأنه يعيش في بلده في أسرة مكونة من الوالدين والإخوة وأبناء له، وهو يعمل هنا وإخوته ووالده يعملون هناك، وله ولدان يدرسان بالثانوية، ووالده يقوم بمصاريف البيت والزرع والأولاد، وهو رجل كبير السن ولم يتعلم ولم يوفر شيئاً لأولاده، فهل يحق لي وأنا هنا وأنا أرسل لهم مبالغ من المال لوالدي، هل يحق لي أن أخفي شيئاً سراً من كسبي احتياطاً لأولادي الذين هم من صلبي أفتوني بارك الله فيكم؟","title":"حكم الإنفاق على الوالدين","answer":"الجواب: الواجب عليك أن تنفق على والدك وعلى أولادك وعلى زوجة والدك بما تستطيع حتى تسد حاجاتهم وما زاد على الحاجة فلك أن تبقيه عندك، ولكن لابد من الإنفاق على والدك وعلى أولادك وعلى زوجة والدك وعلى أولاده أيضاً إذا كان عنده أولاد قاصرون ضعفاء فعليك أن تنفق على الجميع، وهذا من صلة الرحم ومن بر الوالد وهو واجب، أما إن كان والدك غنياً ويستطيع أن ينفق على أولاده وعلى نفسه، فعليك أن تنفق على ولديك اللذين عنده كفايتهما، وتصطلح مع والدك في الشيء الذي يرضيه ولا يلحقك معه حرج في هذا الأمر. نعم.\nالملقي: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6112/حكم-الانفاق-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20102.mp3","categories":["النفقات","بر الوالدين"]},{"id":8365,"question":"أختان نعمل ببلد عربي، فكونا أن نرد شيئاً لوالدينا المسنين من تضحياتهم العظيمة في تربيتنا وتعليمنا، ونحن أكبر أولادهم، فأرسلنا لهم مبلغاً من المال كي يذهبوا لأداء فريضة الحج، ومع الأسف أن هذا التصرف أغضب أزواجنا، رغم عدم تقصيرنا نحوهم، ونحو أولادنا، ورغم أن هذا المبلغ من مالنا الخاص، والله تعالى أوصى بالوالدين كثيراً، فما رأي الدين في هذا أفيدونا أفادكم الله؟","title":"حكم مواساة الزوجة لوالديها من مالها دون رضا زوجها","answer":"الجواب: قد أحسنتما في هذا، والواجب عليكما برهما والإحسان إليهما بجميع الوسائل، أما مساعدتكما للوالدين بما يعينهما على الحج فهذا عمل صالح، وأنتما مشكورتان على ذلك، ولا يجوز لأزواجكما الاعتراض، بل الواجب عليهما أن يساعدا وأن يسرهما هذا الأمر، وأن يشكراكم على هذا العمل.\nالمقصود أن مساعدة الوالدين أو غير الوالدين من رواتبكما ومن مالكما الخاص، ليس للزوج فيه اعتراض، وقد كان النبي ﷺ يأمر النساء بالصدقات، بعد خطبة العيد عليه الصلاة والسلام، فيتصدقن، ولا يقل لهن: شاورن أزواجكن، بل يأمرهن بالصدقة ويقول: إني رأيتكن أكثر أهل النار ويأمرهن بالصدقة والاستغفار، ويأمر بلال أن يأخذ ما يتبرعن به، وقد ثبت عنه ﷺ أن ميمونة قالت: يا رسول الله! أشعرت أني أعتقت فلانة -جاريةً لها-؟ فقال عليه الصلاة والسلام: أما إنك لو أعطيتها أخوالك لكان أعظم لأجرك ولم يقل لها: لم لم تستأذنيني في ذلك؟ بل أمضى عتقها ولكنه أخبرها أنها لو كانت تصدقت بها على أخوالها وساعدت بها أخوالها لكان أعظم لأجرها، من باب صلة الرحم، فكيف بالوالدين؟! الوالدان أعظم وأكبر.\nفالمقصود أن مساعدتكما لوالديكما أمر مطلوب، وحق عليكما، وعلى الأزواج أن يشجعاكم على ذلك، وأن يوافقوا على ذلك، ولكن لا مانع من أخذ خاطر الأزواج، والعناية بما يرضي الأزواج، من دون أن تقصرا فيما يتعلق بالوالدين، وعلى الأزواج أن يتقوا الله وأن يشجعوكم على بر الوالدين، وأن لا يعترضوا على ذلك.","link":"https://binbaz.org.sa/fatwas/6214/حكم-مواساة-الزوجة-لوالديها-من-مالها-دون-رضا-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11405.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":8676,"question":"هذه رسالة وردتنا من العراق من بغداد من المستمعة لقاء محمد لطيف تقول في رسالتها: في حالة إذا ما بعثت الأم ابنها إلى السوق وأوصته بشراء حاجات ما، وأعطته مبلغاً من المال واشترى الابن الحاجات وزاد من المال بعض النقود، فهل حرام عليه أخذ هذا المال دون علمها، مع أنه مال والدته ويحق له كما سمعت من الناس أن يتصرف به أو يأخذ من جيبها مثلاً أو من حقيبتها دون علمها، أفيدوني بارك الله فيكم؟","title":"حكم الأخذ من مال الأب أو الأم بغير إذنهما","answer":"الجواب: ليس له أن يأخذ الفاضل إلا بإذنها فهو وكيل وأمين فعليه أن ينفذ ما قالته والدته أو قاله والده أو غيرهما ممن وكله، وليس له أن يأخذ الفاضل بل عليه أن يرد الفاضل إلى من وكله، سواءً كان الموكل أمه أو أباه أو غيرهما، وليس له أن يأخذ الزيادة، وليس له أن يأخذ من مال أمه إلا بإذنها، ولا من مال أبيه إلا بإذنه، ليس له التصرف في أموالهما إلا بإذنهما، اللهم إلا أن يكون فقيراً وأبوه قصر ولم ينفق عليه وليس له من ينفق عليه سوى أبيه مثلاً، فهذا له أن يأخذ من مال أبيه أو من مال أمه ما قصرا عليه في النفقة، إذا كان في نفقتهما وفي عيالهما وهو عاجز ليس عنده قدرة على التسبب وليس عنده مال، وهو في حضانة أمه أو أبيه، فعليهما أن ينفقا عليه النفقة المعتادة المعروفة في مثل بلدهما أو في أمثالهما، فإذا قصرا عليه فله أن يأخذ من ذلك بالمعروف، يأخذ من مالهما بالمعروف قدر حاجته فقط، أما إذا أرسلاه بمال ليشتري حاجة ليس له أن يأخذ الزيادة بل يرد الزيادة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6816/حكم-الاخذ-من-مال-الاب-او-الام-بغير-اذنهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21503.mp3","categories":["النفقات","بر الوالدين"]},{"id":9260,"question":"أخ من جمهورية مصر العربية بعث برسالة يقول المرسل عبدالرحمن مبروك سلامة له مجموعة من الأسئلة، سؤاله الأول يقول: هل يجوز لوالدي أخذ مصاريف زواجي مني وهو في حالة ميسرة وأنا موظف بسيط ليس لي سوى المرتب؟","title":"حكم أخذ الوالد مصاريف ابنه المعدة للزواج","answer":"الجواب: ليس له ذلك ولا يجوز؛ لقول النبي ﷺ: لا ضرر ولا ضرار حتى لو كان محتاجاً ليس له أن يضرك وعليه أن يستعمل أسباباً أخرى كالقرض والتجارة والأسباب التي يستطيعها في جلب المال، أما أن يضرك فليس له ضررك، فلا يأخذ مالك الذي تتزوج به أو تنفقه على أولادك أو على زوجتك ليس له ذلك وإنما عليه أن يطلب سبباً آخر وعملاً آخر.\nفالحاصل أنه مادام بهذه الحال ميسوراً والحمد لله فليس له أن يأخذ المصاريف التي تعدها للزواج أو تعدها لحاجتك وحاجة أهلك. نعم.\nأما الزيادة فلا بأس لو أخذ منك زيادة فيها فضل أو طلب منك ذلك فلا بأس تعطيه ما طلب، يقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم لكن ليس له أن يضرك. نعم.\nالمقدم: كأني فهمت من السؤال سماحة الشيخ أن الوالد يريد أخذ المصاريف التي دفعها من أجل زواج ابنه والابن هو السائل؟\nالشيخ: الذي فهمنا من كلامه أنه أعد مصاريف ليتزوج بها فيريد أبوه أن يأخذها هذه المصاريف هذه النقود التي أعدها ليتزوج بها يريد أبوه أن يأخذها لينتفع بها هو ويحول بينه وبين الزواج، هذا الذي فهمنا من سؤاله.\nالمقدم: وإذا كان على الفهم الثاني؟\nالشيخ: الفهم الثاني ما هو؟\nالمقدم: إذا كان الوالد قد دفع مصاريف الابن للزواج ثم أراد من الابن أن يسدد تلك المصاريف؟\nالشيخ: هذا فيه تفصيل، إن كان الابن يستطيع فحق أن يسدد وإن كان فقيراً فليس لأبيه حق في هذا، بل عليه أن يزوجه إذا كان أبوه يستطيع. نعم.","link":"https://binbaz.org.sa/fatwas/7423/حكم-اخذ-الوالد-مصاريف-ابنه-المعدة-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15310.mp3","categories":["النفقات","بر الوالدين"]},{"id":9274,"question":"الرسالة التالية من مكة المكرمة وبعثت بها إحدى الأخوات المستمعات تقول ( س . س . ع ) أختنا تقول في سؤال لها: إذا المرأة طلبت من زوجها نقودًا لكي تذهب مثلًا للدكتور أو تشتري شيئًا معينًا وأعطاها برغبته ولم تذهب مثلًا للدكتور أولم تشتر هذا الشيء الذي طلبت النقود من أجله واشترت شيئًا آخر لأولادها وأولاده أيضًا أو ادخرت تلكم الفلوس ليوم ما، فهل تعتبر في هذا عاصية ومخالفة وترجو التوجيه، وأيضًا سمعت أن خروج المرأة بدون إذن من زوجها حرام، ولكني أنا -تتحدث عن نفسها- ولكني أنا أخذت منه الإذن وقلت له: إذا لم تكن موجودًا فسوف أخرج إذا أردت الخروج؟ فقال: أنت مسامحة على ذلك، وترجو التوجيه حيال هذه الأمور، جزاكم الله خيرًا؟","title":"حكم أخذ المرأة شيئًا من مال زوجها تدخره للزمن","answer":"الجواب: إذا أخذت المرأة من زوجها النقود لبعض الحاجات أو للطبيب ثم بدا لها أن لا تذهب وأن لا تشتري هذه الحاجة وأن تحفظ الفلوس لحاجة أخرى أهم أو لحاجات الأولاد أو لحاجات البيت، أو تحفظها ليوم ما فلا بأس عليها في هذا، وهي محسنة وعليها أن تنظر في الأصلح ولا يضرها هذا، بل هذا يدل على كمال العقل وقوة الدين، وقوة البصيرة فلا حرج في هذا.\nإنما الواجب أن تكون هذه الفلوس مصروفة في شيء ينفع لا في إسراف ولا في تبذير ولا في شيء محرم، تحفظها لحاجتها وتصرفها في المصلحة، ولو كانت غير ما أذن فيها الزوج كأن تأخذها للطبيب ثم تقول: أنا طيبة ولا حاجة إلى الطبيب أو تأخذها لشراء حاجة ثم ترى أن غيرها أولى منها، أو ترى أن حفظها لحاجة الأولاد أو لحاجة البيت التي هي أهم، كل هذا لا بأس به والحمد لله.\nأما الخروج فليس لها الخروج إلا بإذنه، فإذا أذن إذنًا عامًا فلا بأس، ومع الإذن العام تتحرى لا تخرج لكل شيء، تخرج للأمور المهمة، ولا تخرج إلى جهات فيها خطر أو فيها تهمة تخرج إلى محلات لا تهمة فيها، ولا خطر فيها، وإذا تيسر أن يكون معها صاحبة فهذا يكون أكمل وأحسن في هذا العصر؛ لأنه أبعد عن الشر والخطر، ولا تخرج إلا عند الحاجات المهمة جدًا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7436/حكم-اخذ-المراة-شيىا-من-مال-زوجها-تدخره-للزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18304.mp3","categories":["الحقوق الزوجية","النفقات"]},{"id":9276,"question":"هل زواج الابن واجب على الأب أم لا؟","title":"حكم تزويج الأب الغني ابنه","answer":"","link":"https://binbaz.org.sa/fatwas/7439/حكم-تزويج-الاب-الغني-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15409.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":9322,"question":"وهذه رسالة وردت إلى البرنامج من السائلة (ب. ع. أ) من السودان، تقول: أنا ربة بيت وزوجي صاحب دكان كان يعطيني قليلاً من السكر لعمل حلوى لأبيعها والعائد من بيعها أدخله في بعض ضروريات المنزل التي يحجم زوجي عن إحضارها، والآن رفض زوجي إعطائي هذا السكر وأنا آخذه بالخفاء، فما الحكم في ذلك؟","title":"حكم أخذ المرأة من مال زوجها للضرورة بدون علمه","answer":"الجواب: لا حرج إذا كان لمصلحة البيت وحاجة البيت المعتادة التي ليس فيها إسراف ولا تبذير فلا بأس، ثبت عن رسول الله ﷺ أن هند بنت عتبة زوجة أبي سفيان بن حرب سألت النبي ﷺ فقالت: يا رسول الله! إن أبا سفيان لا يعطيني من النفقة ما يكفيني ويكفي بني، هل علي جناح إن أخذت من ماله بغير علمه ما يكفيني ويكفي بني؟ فقال النبي ﷺ: لا حرج، خذي من ماله بالمعروف ما يكفيك ويكفي بنيك، فرخص لها النبي ﷺ أن تأخذ من ماله ما يكفيها ويكفي أولادها بالمعروف، يعني: بالمتعارف الذي ليس فيه إسراف ولا تبذير، فإذا أخذت من ماله سكراً أو غيره من النقود لهذه الحاجة، لحاجة البيت وحاجة الأطفال المعتادة فلا حرج في ذلك، ولو بغير علمه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7489/حكم-اخذ-المراة-من-مال-زوجها-للضرورة-بدون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23707.mp3","categories":["النفقات","بر الوالدين"]},{"id":9464,"question":"لها سؤال آخر تقول: إن زوجي قال لي: عليك الحرج إذا اشتريت لأولادي شيئاً من مالك أو مال أهلك، وهو لا يحافظ على الصلاة جيداً، ويأكل المحرمات التي حرم الله كالحبوب والخمر إلى آخرها، فهل هذا الحرج يلزمني، يعني: هل تحريجه هذا يلزمني أفيدوني أفادكم الله؟","title":"حكم منع الزوجة من الإنفاق على أبنائه من مالها","answer":"الجواب: إذا كان يقوم بحقهم ويعطيك حاجتهم فلا تأخذي لهم من أحد شيئًا، أما إذا كان قصر أو تركهم بدون كسوة، ومن دون حاجاتهم فلا بأس، ولكن ما دام يقوم بحاجاتهم فامتثلي أمره، وإن كان في نفسه عنده معاصي، لكن إذا كان لا يصلي لا تبقين معه؛ لأن من لا يصلي كافر، إذا كان لا يصلي فالذي لا يصلي كافر نسأل الله العافية، أما إذا كان يصلي ولكن قد يفعل بعض المحرمات فهذا عاصي وأنت بالخيار، إن صبرت عليه فلا بأس، وإن طلبت الفراق فهذا إلى المحكمة تتصلين بالمحكمة أنت وإياه والمحكمة تنظر في أمركما. نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7621/حكم-منع-الزوجة-من-الانفاق-على-ابناىه-من-مالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25510.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":10260,"question":"يقول: إنها لا تنفق من راتبها إلا النصف والنصف الآخر تضعه في البنك؟","title":"حكم نفقة الزوجة على زوجها","answer":"","link":"https://binbaz.org.sa/fatwas/8431/حكم-نفقة-الزوجة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27910.mp3","categories":["النفقات","بر الوالدين"]},{"id":10559,"question":"سماحة الشيخ! ما الحكم إذا كان الشخص يأكل حراماً وله أبناء وله أناس يعولهم، كيف يتصرفون والحالة هذه؟","title":"حكم إعالة الأبناء والزوجة من مال حرام","answer":"الجواب: الحال فيهم مختلفة، المضطر نرجو أن لا يكون عليه شيء كالصبيان الصغار وأشباههم لأنهم هو الذي يعولهم فالإثم عليه. وأما الزوجة التي تعلم هذا فلها أن تطلب الطلاق وتفارقه؛ لأن هذا عذر لها شرعي، إذا كان كسبه خبيث فلها العذر أن تطلب الطلاق وأن تذهب إلى بيت أهلها وتطالب بتغيير الكسب أو بالطلاق حتى لا تبقى مع من يأكل الحرام.\nأما إذا كان عنده كسب طيب ولكن في ماله اختلاط في ماله شيء من الشبهة فهذا أسهل والأمر فيه أوسع، أما إذا كان معروفاً بالكسب الخبيث وأن كسبه كله خبيث هذا لزوجته العذر ولأولاده العذر في أن لا يأكلوا من بيته كذلك الكبار المشردين العارفين، وأما المضطرون من أولاده الصغار والفقراء لا حيلة لهم فنرجو أن يعفو الله عنهم إذا أكلوا من ماله عند الضرورة، حتى يجعل الله لهم فرجاً ومخرجا.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8733/حكم-اعالة-الابناء-والزوجة-من-مال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32203.mp3","categories":["النفقات","بر الوالدين"]},{"id":10626,"question":"المستمع (ع. محمد .ع) سوداني مقيم في الدوادمي، بعث بسؤال طويل، ملخصه: إذا احتاج الابن إلى شيء من المال وطلب أباه فلم يجبه إلى طلبه؛ فاضطر الابن إلى السرقة من مال أبيه دون أن يعلم الأب، هل على الابن إثم؟","title":"حكم أخذ الولد من مال أبيه دون علمه","answer":"الجواب: هذا فيه تفصيل: إن كان الأب قصر في النفقة والولد ضعيف ما يستطيع العمل عاجز، فإنه يأخذ من مال أبيه ما يسد حاجته، ولو بغير علمه، وهكذا الزوجة تأخذ من مال زوجها بغير علمه ما يسد حاجتها وحاجة أطفالها؛ لما ثبت في الصحيحين عن عائشة رضي الله عنها أن هند بنت عتبة رضي الله عنها زوجة أبي سفيان قالت: يا رسول الله! إن أبا سفيان رجل شحيح، -يعني: بخيل- لا يعطيني ما يكفيني ويكفي بني إلا ما أخذته من ماله بغير علمه، فهل علي في ذلك من جناح؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك فرخص لها أن تأخذ من ماله بالمعروف ما يكفيها ويكفي أولادها.\nفهكذا الولد إذا كان قاصر يدرس ضعيف ما عنده شيء يقوم بحاله وأخذ من مال أبيه كسوة له أو غداء أو عشاء يسد حاجته فلا حرج عليه، أو كان أبوه موسراً والولد ليس عنده شيء وهو في حاجة إلى الزواج، وأخذ من مال أبيه ما يتزوج به؛ لأنه عاجز وأبوه قادر وعنده مال كثير فلا حرج عليه، فإن الواجب على الأب أن يعف ولده بتزويجه. نعم.\nالمقدم: جزاكم الله خيراً، وهذا واجب على الأب سماحة الشيخ؟\nالشيخ: نعم إذا كان قادراً والولد عاجز، أما إذا كان الولد قادراً فليس له أن يأخذ من مال أبيه شيء، بل عليه أن يأخذ من ماله، وينفق من ماله. نعم.\nالمقدم: بارك الله فيكم، والزواج؟\nالشيخ: والزواج كذلك، يتزوج من ماله، إذا كان قادر يتزوج من ماله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8814/حكم-اخذ-الولد-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32816.mp3","categories":["النفقات","بر الوالدين"]},{"id":10690,"question":"هل يجوز الكذب على الوالد إذا عمل الولد عملاً غير مرضٍ؛ خوفاً من ضربه، أو التكلم عليه بكلام يكرهه؟","title":"حكم الكذب على الوالد خوف العقوبة إن صدق","answer":"الجواب: إذا كان الكذب لا يضر أحداً، إنما يخلصه من غضب أبيه ولا يضر أحداً فلا بأس بذلك، كأن يقول: ما ذهبت المحل الفلاني، ولا كلمت فلاناً، وذلك لا يضر أحداً، فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8870/حكم-الكذب-على-الوالد-خوف-العقوبة-ان-صدق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33020.mp3","categories":["النفقات","بر الوالدين"]},{"id":10833,"question":"هل يأثم الوالدان إذا لم يعطيا ابنهما المال لكي يتزوج، بحجة أنه يجب عليه أن يكمل الدراسة الجامعية، ثم يعمل ويحصل على الأموال من عمله لكي ينفقها على زوجته؟","title":"حكم تزويج الوالدين لولدهما","answer":"الجواب:  إذا كان الوالدان يستطيعان أن يزوجاه وجب عليهما تزويجه، ولا يجوز تأخير ذلك إلى أن يكمل الدراسة؛ لأنه معرض للفتنة، فالواجب على والديه إعفافه وإعانته على الخير، إذا كانا قادرين أو أحدهما، فأما إذا كانا عاجزين فليس عليهما حرج فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا كان أبوه غنيًا يستطيع تزويجه، أو أمه كذلك، فإن الواجب عليهما تزويجه وعدم تأخير ذلك إذا طلب ذلك، بل يجب أن يحرصا على ذلك، ليصوناه عما حرم الله، وليجتهدا في سلامته، فكما يجب عليهما أن ينفقا عليه ما يسد حاجته ويستر عورته فالإنفاق عليه فيما يبعده عن الحرام ويسبب غض بصره وحفظ فرجه أهم من ذلك. نعم والله المستعان. المقدم: جزاكم الله خيرًا، الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9018/حكم-تزويج-الوالدين-لولدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35511.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":10839,"question":"هل يأثم الوالدان إذا لم يعطيا ابنهما المال لكي يتزوج، بحجة أنه يجب عليه أن يكمل الدراسة الجامعية، ثم يعمل ويحصل على الأموال من عمله لكي ينفقها على زوجته؟","title":"حكم تزويج الوالدين لولدهما","answer":"الجواب:  إذا كان الوالدان يستطيعان أن يزوجاه وجب عليهما تزويجه، ولا يجوز تأخير ذلك إلى أن يكمل الدراسة؛ لأنه معرض للفتنة، فالواجب على والديه إعفافه وإعانته على الخير، إذا كانا قادرين أو أحدهما، فأما إذا كانا عاجزين فليس عليهما حرج فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا كان أبوه غنيًا يستطيع تزويجه، أو أمه كذلك، فإن الواجب عليهما تزويجه وعدم تأخير ذلك إذا طلب ذلك، بل يجب أن يحرصا على ذلك، ليصوناه عما حرم الله، وليجتهدا في سلامته، فكما يجب عليهما أن ينفقا عليه ما يسد حاجته ويستر عورته فالإنفاق عليه فيما يبعده عن الحرام ويسبب غض بصره وحفظ فرجه أهم من ذلك. نعم والله المستعان. المقدم: جزاكم الله خيرًا، الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9018/حكم-تزويج-الوالدين-لولدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35511.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":11038,"question":"السائل: أحمد إبراهيم يقول: ما حكم من كان له ابن معوق، وتصرف له مساعدة سنوية من الحكومة، فهل مطلوب منه أن يجعلها للطفل المعوق فقط، أو يجمعها ويشتري له شيئًا يخصه عن إخوته، أم يحق للوالدين ولبقية الإخوة الانتفاع بها سماحة الشيخ؟","title":"حكم تصرف الوالد في مال ولده","answer":"الجواب:  والده مخير، إن شاء حفظها، وإن شاء أنفقها عليه، أو أكلها الوالد؛ لأن الوالد: أنت ومالك لأبيك فإن شاء أنفق عليه من ماله، وإن شاء أنفق عليه مما قررته الحكومة له، وإن شاء حفظه له، كل ذلك إلى الوالد، لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/9216/حكم-تصرف-الوالد-في-مال-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28720.mp3","categories":["النفقات","بر الوالدين"]},{"id":11051,"question":"هذا السائل أرسل بهذه الرسالة جابر من محايل عسير يقول: لي أولاد كبار وأنا رجل مسن، وهؤلاء الأولاد لا يعملون، ولم أقم بالتقصير عليهم في تربيتهم، وعندما أصبحت مسنًا فروا مني، وعندما أطلب منهم المساعدة لا يقومون بمساعدتي، وهناك شخص آخر من الأولاد يستلم راتبًا، وما زال يطلب مني الزواج بإلحاح، وأنا فقير، علمًا بأنه لا يقوم بمساعدتي وجهوني سماحة الشيخ.","title":"حكم رفض الأبناء النفقة على والدهم المعسر","answer":"الجواب:  الواجب عليهم أن يتقوا الله، وأن يساعدوك، وأن ينفقوا عليك ما دمت في حاجة، هذا هو الواجب عليهم إذا كان عندهم قدرة، فالواجب عليهم أن ينفقوا عليك حاجتك، وهكذا الولد الآخر يجب عليه أيضًا أن ينفق حسب طاقته، وليس عليك تزويجه لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] لكن لو كنت قادرًا وهو عاجز يلزمك التزويج، لو كنت قادرًا وهو عاجز، أما الآن ما دمت عاجزًا فليس عليك شيء، وعليه أن ينفق عليك مع إخوانه، ينفق عليك حاجتك كما أن إخوانه كذلك يلزمهم، حسب طاقتهم أن ينفقوا عليك؛ لأن الله -جل وعلا- أوجب صلة الرحم، وبر الوالدين، ومن أعظم البر أن ينفقوا على والدهم إذا احتاج إليهم، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9229/حكم-رفض-الابناء-النفقة-على-والدهم-المعسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28807.mp3","categories":["النفقات","بر الوالدين"]},{"id":11269,"question":"هل يجب على الأبناء إعطاء والدهم رواتبهم الشهرية إذا كان الابن بحاجة للمال ووالده مقتدر ماليًا؟","title":"حكم إلزام الوالد المقتدر ولده المحتاج بإعطاء مرتبه الشهري","answer":"الجواب: لا يلزم الأولاد أن يعطوا رواتبهم آباهم إذا كانوا في حاجة إليها، إنما يعطى من الفضل؛ لقول النبي ﷺ: لا ضرر ولا ضرار وقوله ﷺ: ابدأ بنفسك ثم من تعول فالإنسان يبدأ بنفسه وأهل بيته زوجته وأولاده، فإذا فضل شيئًا وأعطى والده فلا بأس، أما إن كان والده فقيرًا عليه أن ينفق عليه، يلزمه أن ينفق على والده مع أولاده، أما أن يعطيه وهو غير محتاج فلا لا يلزمه ذلك، إلا بعد فضل ذلك عن الحاجة الضرورية، ولهذا يقول ﷺ: ابدأ بنفسك ثم من تعول، ويقول في الحديث الآخر: لا ضرر ولا ضرار، فليس للأب أن يضار ولده والجد كذلك، ولكن الولد يعطي أباه ويعطي جده مما يسر الله فاضلًا عما يلزمه، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9458/حكم-الزام-الوالد-المقتدر-ولده-المحتاج-باعطاء-مرتبه-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37509.mp3","categories":["النفقات","بر الوالدين"]},{"id":11286,"question":"يقول: لي أولاد في المدرسة منهم الكبير ومنهم الصغير، وعندما أمنحهم بعض النفقات الشخصية أفضل الكبير على الصغير، فهل هذا جائز؟","title":"حكم إعطاء الوالد لولده الكبير نفقة أكثر من الصغير","answer":"الجواب:  على حسب مصروف المدرسة مثلًاإذا كان حاجة الكبير أكثر يعطى قدر حاجته لا لأجل ذاته، بل يعطى ما يحتاجه في التعلم لأن نفقة الكبير قد تكون أكثر فيما يحتاجه من دفاتر أو كتب أو غير ذلك. فالحاصل: أنه يعطى قدر حاجته في التعليم وإن كان أكثر من الصغير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9467/حكم-اعطاء-الوالد-لولده-الكبير-نفقة-اكثر-من-الصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37518.mp3","categories":["النفقات","بر الوالدين"]},{"id":11607,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد منصور محمد عسيري، الأخ أحمد له قضية مطولة بعض الشيء، ملخصها أنه تزوج، وكلفه ذلكم الزواج مبالغ كبيرة، وحينئذٍ احتاج إلى والده ليعينه على تكاليف الحياة الزوجية، وعلى العيش مع زوجته، إلا أن والده أعرض عنه، ولم يعنه بشيء، وحينئذ يرجو من سماحتكم التوجيه له ولأمثاله، جزاكم الله خيرًا.","title":"حكم إعانة الأب لابنه على الزواج","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن التزوج من أهم المهمات، ومن السنن المشروعة وقد يجب مع القدرة، لقول النبي -عليه الصلاة والسلام-: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء. هذا الحديث يدل على وجوب التزوج مع القدرة، لما في ذلك من المصالح العظيمة من إحصان الرجل، وحمايته من أسباب الفتنة، ولما يترتب عليه من الذرية، وتكثير الأمة، فإذا كان الرجل لا يستطيع، وأبوه يستطيع؛ وجب على أبيه أن يزوجه؛ لأن نفقة الزواج مثل نفقة الأكل والشرب والكسوة، يجب على الوالد أن ينفق على أولاده ما يحتاجون إليه، من طعام وكسوة، كما يجب عليه أيضًا أن ينفق عليهم مؤونة الزواج؛ لأن كل إنسان في حاجة إلى ذلك، إذا استطاع ذلك. أما إذا لم يستطع فهو معذور فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فالذي أنصح به جميع المسلمين أن يجتهدوا في تزويج أبنائهم وبناتهم، وأن يساعدوا في ذلك؛ حرصًا على عفتهم، وبعدهم عن الشر، وعملًا بالنصوص الدالة على ذلك، كقوله سبحانه في كتابه العظيم: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] وقوله -جل وعلا-: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3] ولهذا الحديث قوله ﷺ: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج الحديث، وقوله ﷺ: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة. فالواجب على الآباء أن يزوجوا أولادهم العاجزين إذا كان الوالد يستطيع تزويج ولده، وعليه أيضًا أن يسعى في تزويج البنت، ويحرص، وهكذا الأخت إذا لم يكن لها والد، يحرص أخوها على تزويجها إذا خطبها الكفء، ولا يفعل ما يعرقل الزواج بغير وجه شرعي؛ لأن في الحرص على تزويج البنين والبنات إعانة لهم على الخير، وعلى العفة عن أسباب الشر، فالواجب على الجميع التعاون في ذلك الرجال والنساء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذا كان هذا الابن له دخل، ولكنه فرط في دخله، وعبث به هنا وهناك، هل على الوالد إذًا.. الشيخ: المعتبر حال الزواج، إذا كان حال الزواج عنده قدرة لا يجب على الوالد إعطاؤه في ذلك شيئًا، إلا إذا أعطى إخوته مثله، أما إذا كان الولد عنده أموال يستطيع بها الزواج فإنه لا يلزم الوالد أن يساعده في ذلك، كون الولد قد يكون عنده شيء من السفه، وقد فرط في بعض الأموال، العبرة بحال النكاح، والتفريط السابق لا يمنع من المساعدة.","link":"https://binbaz.org.sa/fatwas/9790/حكم-اعانة-الاب-لابنه-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38801.mp3","categories":["النفقات","بر الوالدين"]},{"id":11941,"question":"له قضية أخرى سماحة الشيخ يقول فيها: كما سبق وذكرت أنني استقلت من العمل، ومريض، وليس لي دخل، ولي أسرة كبيرة، وعندما أطلب المساعدة من والدي وإخوتي يرفضون مساعدتي، ويقولون: ليس لك حق علينا في مساعدتك، رغم أنني عندما كنت أعمل، وعندما كنت مقتدرًا كنت أخصص لوالدي مبلغًا من المال، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"واجب الوالد تجاه ولده المحتاج والعاجز عن العمل","answer":"الجواب:  الواجب على والدك، وعلى إخوتك أن يساعدوك، وأن يعطوك من أموالهم ما يعينك إذا استطاعوا ذلك، ولعل امتناعهم من مساعدتك لقصد حثك على العمل حتى لا تكسل، ولعلهم يكذبونك في دعوى العجز، فأنت اتق الله، وبادر بالعمل حتى تستغني عنهم، وعن غيرهم، اجتهد في العمل في التجارة، في الوظيفة إذا تيسرت وظيفة مباحة طيبة، في الخدمة في العمل، خطاط بناء، حداد، نجار، اجتهد في العمل الذي تستطيعه، يقول النبي ﷺ لما سئل: أي الكسب أطيب؟ قال -عليه الصلاة والسلام-: عمل الرجل بيده، وكل بيع مبرور ويقول ﷺ: ما أكل أحد طعامًا خيرًا من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده. فاتق الله، واعمل، واجتهد في أي عمل؛ يدر عليك من الأعمال المباحة الطيبة، فإن عجزت؛ فالواجب عليهم أن ينفقوا عليك، ولا مانع أن تسأل من إخوانك الأغنياء أن يساعدوك من الزكاة وغيرها، إذا كنت صادقًا في أنك عاجز عن العمل، ولم يحصل لك وظيفة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10126/واجب-الوالد-تجاه-ولده-المحتاج-والعاجز-عن-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42805.mp3","categories":["النفقات","بر الوالدين"]},{"id":12185,"question":"هل يجوز للمرأة أن توفر النقود من مصروفها ومصروف البيت والأولاد دون علم زوجها، مع العلم أن ذلك لا يؤدي إلى بخل أو تقتير، بل من باب عدم الإكثار والإسراف في المصاريف، يعني: الاقتصاد في المصروف؟","title":"حكم ادخار الزوجة من مصروف بيتها دون علم زوجها","answer":"الجواب:  إذا كان ذلك لمصلحة شرعية، وهو عدم الإسراف، وعدم التبذير؛ فهي مأجورة، لكن تخبر الزوج بذلك، تخبر الزوج بذلك حتى يصرف المال في جهة أخرى، أما أن تدخره لنفسها دون علم الزوج؛ فلا، فإذا كان الاقتصاد لمصلحة البيت، ومصلحة الزوج، وعن علم الزوج؛ فلا بأس بذلك؛ لأن الاقتصاد مطلوب، والإسراف محذور، والتبذير كذلك. فينبغي للمرأة أن تكون مقتصدة، فإذا كان الزوج يتساهل، فينبغي لها أن تكون عندها عناية بالمصارف؛ حتى لا تصرف إلا في الوجه المناسب؛ وحتى تبتعد عن التبذير والإسراف، وإذا كان الزوج يتساهل؛ فلا ينبغي لها أن تتساهل، والمال سوف ينفعهما جميعًا، نعم. المقدم: أما دون علم الزوج كما تقول؟ الشيخ: ......... لا، لابد أن تخبره بذلك حتى يكون على بينة، وليس لها أن تأخذه لنفسها المال، بل يكون للزوج، ولمصلحة الزوج والأولاد وأهل البيت؛ حتى يكون على بينة هو؛ لأنه إذا لم تخبره قد يزين لها الشيطان أن تصرفه في حاجات أخرى لها، تخص بها نفسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10371/حكم-ادخار-الزوجة-من-مصروف-بيتها-دون-علم-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44312.mp3","categories":["النفقات","بر الوالدين"]},{"id":12510,"question":"بعد هذا رسالة وصلت إلى البرنامج من الرياض باعثها مستمع رمز إلى اسمه بالحروف (م) و (ط) يقول: صدرت من زوجتي بعض التصرفات التي أساءت إلى والدتي التي كانت في زيارة لي بالمملكة، رغم أن والدتي تتمتع بأخلاق عالية، وهي دائمة العطف والحنان على الجميع، وتخص زوجتي بقدر كبير من ذلك منذ زواجي بها قبل أربع سنوات مضت، حتى إن أخواتي البنات يحسدونها على ذلك، إلا أن زوجتي قابلت الإحسان بالإساءة، ولم تراع كبر سن والدتي، أو كونها في زيارة لنا قد لا تتكرر، أرجو توجيهي ماذا أفعل، هل أطلق زوجتي؟ جزاكم الله خيرًا.","title":"كيفية معالجة أخطاء الزوجة تجاه أم زوجها","answer":"الجواب:  نوصيك بعلاج الموضوع بالكلام الطيب، والأسلوب الحسن، ولا تعجل في الطلاق، ولكن توصيها بالكلام الطيب، والأخلاق الفاضلة، والمعاملة الطيبة مع والدتك، ومع غيرها من أقاربك، ومن زوارك، عليها أن تتقي الله، وعليها أن تراقب الله حتى تكون زوجة صالحة ذات أخلاق كريمة مع الوالدة ومع غيرها، ولا تعجل في الطلاق إذا كانت دينة، إذا كانت من أهل الخير والصلاح لا تعجل، أما إذا كان عندها أخلاق أخرى سيئة من المعاصي فطلاقها أصلح، إذا لم ينفع فيها الوعظ والتذكير، أما هذه الزلة مع الوالدة فعالجها بالكلام الطيب, والأسلوب الحسن، والتوجيه إلى الخير، وإذا دعت الحاجة إلى تأديبها تأديبًا خفيفًا؛ فلا بأس، أو بالهجر؛ كذلك لا بأس، لكن مهما أمكن العلاج بغير الهجر والتأديب؛ فهو أولى، فعليك أن تجتهد في ذلك، وأن تسأل الله لها الهداية والتوفيق وصلاح الحال، هذا هو الأولى بك، نعم. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/10708/كيفية-معالجة-اخطاء-الزوجة-تجاه-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40703.mp3","categories":["النفقات","بر الوالدين"]},{"id":13373,"question":"هذا سائل للبرنامج يقول في هذا السؤال أحمد مصري، ويعمل بالرياض، يقول: أبي تزوج بامرأة غير أمي، وذلك منذ عشر سنوات، وهو الآن لا يراها، ولا ينفق عليها، ولا علينا، فما الواجب علينا تجاهه، وبماذا تنصحوننا مأجورين؟","title":"توجيه لمن لا ينفق على زوجته وأولاده","answer":"الجواب: إذا كانت راضية وسامحة؛ لا شيء عليه، إذا سمحت أمك أنها تبقى في عصمته، ولا ينفق، ولا يراها؛ فلا بأس، الرسول ﷺ أراد أن يطلق سودة، فقالت: \"يا رسول الله! أبقني في حبالك وحقي ساقط، ويومي لعائشة\" فوافق النبي ﷺ وبقيت في حباله، ولا يأتيها، ولا ينظر إليها، ولا ينفق عليها، فإذا سمحت أمك، ورضيت عنه؛ فلا حرج. أما إذا قالت: لا، أنا ما أرضى، إما أنفق، وإلا طلق؛ يلزمه الطلاق، يلزمه أن يطلق طلقة واحدة، أما إذا كانت لا، راضية تقول: لا، أنا صابرة، وأبغى عند عيالي، وأنت مسامح، ولا تجيني، ولا تنفق، أنا أصنع نفسي؛ فلا حرج، والحمد لله، لكن إذا كانت لا، تقول: لا، إما اعدل، وإلا طلق؛ يلزمه إما العدل، وإلا الطلاق، هذا الواجب.  المقدم: جزاكم الله خيرًا. المقدم: يقول في سؤال له سماحة الشيخ: بالإضافة إلى هجره لأمنا فهو يعاملنا بقسوة، ولا يعطينا شيئًا، علمًا بأنه يملك الكثير من الأموال مما أحدث في قلوبنا شيء من الكراهية له، فماذا توجهونه مأجورين؟ الشيخ: الواجب عليه أن ينفق على أولاده إذا كانوا فقراء، الواجب عليه أن ينفق عليهم، وأن يعاملهم باللطف، والإحسان، والخلق الحسن، والواجب على الأولاد أيضًا أن يعرفوا قدره، وأن يبروه، وأن يخاطبوه بالتي هي أحسن، وإذا دعت الحاجة إلى أن يرفعوا الأمر إلى المحكمة؛ فلا بأس، يقولون: والدنا احنا فقراء، ولم ينفق علينا، يرفعوا الأمر إلى المحكمة، وإذا توسط لهم بعض الطيبين من الجيران والأقارب لدى الوالد، حتى ينفق؛ فهذا أحسن من المحكمة، أحسن من الخصومة. وصيتي للأولاد: الرفق، والبر بالوالد، والكلام الطيب مع الوالد، ووصيتي للوالد أن يتقي الله، وأن ينفق على أولاده المحتاجين، وأن لا يحوجهم إلى الشكوى إلى المحكمة، أو إلى توسط الناس، يجب أن يعدل من نفسه، وأن يعرف ما أوجب الله عليه، وأن ينفق عليهم ما داموا فقراء، وأن يحسن إليهم، وألا يحوجهم إلى شكوى، ولا إلى غيرها، وعلى الأولاد جميعًا أن يجتهدوا في بر والدهم، والكلام الطيب معه، ومخاطبته بالتي هي أحسن، وإذا دعت الحاجة إلى أن يطلبوا من أعمامهم، أو من بعض جيرانهم، أو أصدقاء والدهم أن يتوسطوا لدى والدهم في الإحسان إليهم، وفي أداء حقهم بدلًا من الشكوى؛ فهذا أطيب، وأحسن. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11664/توجيه-لمن-لا-ينفق-على-زوجته-واولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51506.mp3","categories":["النفقات","نصائح وتوجيهات"]},{"id":13589,"question":"السائل في ثاني أسئلته يقول: سماحة الشيخ! إذا حدث سوء تفاهم، أو شجار بين الزوج وزوجته تقوم الزوجة بالذهاب إلى أهلها فترة من الزمن، وعندما يريد الزوج أن يعيدها إلى بيته، وحل الخلافات بينهما؛ يفاجأ بأهل الزوجة بطلب مبالغ كبيرة من المال، وذلك حق الجلوس عند أهلها، هل يجوز إعطاء أهل الزوجة مثل هذه المبالغ، وذلك مقابل قعود هذه المرأة عند أهلها؟","title":"حكم دفع المال مقابل جلوس الزوجة عند أهلها","answer":"الجواب:  نعم، أحسن حتى تتم العشرة، وتبقى المودة، وإن تيسر استسماحهم، أو التوسيط إلى من يستسمحهم في الكل، أو البعض؛ فلا بأس، وإذا تيسر أن ترضيها بما قال أهلها، وتعطيهم ما طلبوا؛ لعل ذلك يكون فيه خير كثير لكما جميعًا؛ لأجل تهدأ الأوضاع، وتستقيم الأحوال، وتستمتع بزوجتك بحالة طيبة. على كل حال هذا يرجع إليك إن سمحت، فهذا خير عظيم، ولا سيما مع القدرة، وإن شق عليك ذلك توسط لها الأخيار، والطيبين حتى يصلحوا بينك وبينهم بوضع التكاليف هذه، أو بعضها. نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11949/حكم-دفع-المال-مقابل-جلوس-الزوجة-عند-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53319.mp3","categories":["النفقات","بر الوالدين"]},{"id":13642,"question":"في أسئلة هذا السائل من جمهورية مصر العربية يقول: متى تبدأ النفقة على الزوجة، هل هو من العقد، أم من الدخول عليها؟","title":"متى تبدأ النفقة على الزوجة؟","answer":"الجواب: يبدأ من الدخول عليها، إذا دخل عليها، وصارت تحت تصرفه، وتحت نفقته تبدأ النفقة عليها، أما مادامت عند أهلها؛ فلا نفقة لها إلا إذا كان التأخير منه هو الذي أخرها، أما إذا كان الامتناع منهم، طلبوا منه تأجيلها؛ فإن النفقة عليهم. أما إذا هو الذي تركها عندهم متساهلًا؛ فالظاهر أن عليه النفقة؛ لأن هذا التساهل يشبه أن يكون فرارًا من النفقة، وقد دخلت في عصمته، والله -جل وعلا- أمر بالمعاشرة بالمعروف، قال: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وليس من المعروف أن لا ينفق عليها، وقال النبي ﷺ: ولهن عليكم رزقهن وكسوتهن بالمعروف وهذا يعم المدخول بها، وغير المدخول بها، إلا إذا كان بقاؤها عند أهلها باختيارهم، ورغبتهم هم فالنفقة عليهم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11975/متى-تبدا-النفقة-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52815.mp3","categories":["النفقات","بر الوالدين"]},{"id":13872,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":13886,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":14190,"question":"السائل إبراهيم عبد العزيز له هذا السؤال، يقول: سماحة الشيخ! يوجد لي ولله الحمد ثلاثة بنات وولد، وأكبرهم بنت عمرها الآن ستة عشر عامًا، وولدت هذه البنت معوقة في ساقها، وقام الطبيب بإجراء عملية في بتر ساقها وتركيب جهاز لتمشي عليه، والحمد لله هي الآن تمشي عادي، ولكن هل علينا إثم في هذه العملية، وثانيًا هذه البنت تقوم بتغيير هذا الجهاز في كل ثلاث سنوات أو أربع ويتكلف مبلغًا من المال، هل إذا قمت بترك مبلغ من المال باسم البنت لتتمكن من تبديل الجهاز وقت ما تحتاج لذلك هل أكون قد ظلمت باقي الأخوات؟","title":"حكم الزيادة في النفقة لبعض الأبناء للحاجة","answer":"الجواب: إذا كانت فقيرة، لا، هذا واجب أنت تنفق عليها مثل نفقتها، هذا من باب النفقة ليس من باب العطية، فأنت مأجور ولا حرج، إذا كانت فقيرة محتاجة إلى ذلك ليس عندها مال. نعم. الله المستعان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12643/حكم-الزيادة-في-النفقة-لبعض-الابناء-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54722.mp3","categories":["النفقات","بر الوالدين"]},{"id":14504,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع وعدم اهتمامه، فما رأيكم في هذا؟","title":"حكم هجر الزوجة الأولى وترك النفقة عليها وعلى أبنائها","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، وقد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة هذا عليه إثم في ذلك، إلا إذا كان خيّرها بين الطلاق وبين الصبر فلا حرج عليه، إذا خيّرها واختارت البقاء معه على ظلمه، وعدم عدله فلا بأس عليه إذا خيّرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديه مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف، من غير تبذير، ومن غير إسراف فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، وحتى يشيروا عليه؛ لعله يهتدي، ولعله يقوم بالواجب.  وينبغي لها أن تكثر من سؤال الله له الهداية، حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل.\nولكن مهما أمكن أن يكون ذلك من طريق المصلحين، من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينهم، بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، هذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12999/حكم-هجر-الزوجة-الاولى-وترك-النفقة-عليها-وعلى-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63304.mp3","categories":["قضايا المرأة","النفقات","الحقوق الزوجية"]},{"id":14511,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع وعدم اهتمامه، فما رأيكم في هذا؟","title":"حكم هجر الزوجة الأولى وترك النفقة عليها وعلى أبنائها","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، وقد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة هذا عليه إثم في ذلك، إلا إذا كان خيّرها بين الطلاق وبين الصبر فلا حرج عليه، إذا خيّرها واختارت البقاء معه على ظلمه، وعدم عدله فلا بأس عليه إذا خيّرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديه مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف، من غير تبذير، ومن غير إسراف فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، وحتى يشيروا عليه؛ لعله يهتدي، ولعله يقوم بالواجب.  وينبغي لها أن تكثر من سؤال الله له الهداية، حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل.\nولكن مهما أمكن أن يكون ذلك من طريق المصلحين، من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينهم، بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، هذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12999/حكم-هجر-الزوجة-الاولى-وترك-النفقة-عليها-وعلى-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63304.mp3","categories":["قضايا المرأة","النفقات","الحقوق الزوجية"]},{"id":14557,"question":"هذه أختكم في الله (ح. م. ح) كتبت مجموعة من الأسئلة بأسلوبها الخاص تقول سماحة الشيخ: امرأة متزوجة برجل لا يوفر لها، ولا لأولادها أبسط أسباب المعيشة، فهو يعمل يومًا، ويستريح أسبوعًا، وأصبح الأولاد كأنهم أيتام، يتصدق عليهم الجيران، ومن يرى من حالتهم يعطف عليهم، ويقدم لهم الصدقة، تقول: هي تنصحه وتطالبه بسد حاجات البيت والأولاد، ولكن لا حياة لمن تنادي، فأصبحت هي وهو في شجار دائم، فتذكر أيضًا يا سماحة الشيخ بأنها تقول: بأنني لا أقوم بخدمته هل أأثم في ذلك؟ وهل أسأل عن تعاملي معه أمام الله ؟","title":"حكم ترك خدمة الزوج المقصر في النفقة","answer":"الجواب: أيها السائلة أنت بالخيار إن صبرت فلا بأس، وإن لم تصبري فارفعي الأمر للمحكمة، لك أن تطلبي الطلاق؛ لأنه لا يقوم بالواجب، وإن صبرت وتعاونت معه فلا بأس عليك، ولا يلزمك طاعته فيما لا تستطيعين، كأوقات طلب الرزق لأولادك، وأما في الأوقات التي تستطيعين فاستجيبي له في حاجاته، وإذا طلبك في وقت لا تستطيعين الإجابة فأنت معذورة، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فعليك طاعته فيما تستطيعين، ولا حرج عليك فيما لا تستطيعين، كوقت طلب الرزق لأولادك ولنفسك؛ لأنه لا يقوم بالنفقة، والأوقات الأخرى التي يمنعك مرض أو عذر شرعي كالحيض، أو ما أشبه ذلك. المقصود: عليك طاعته حسب الطاقة، فيما أباح الله وشرع الله، ولك طلب الفرقة، وطلب الطلاق عند المحكمة؛ لأنه لم يقم بالواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13053/حكم-ترك-خدمة-الزوج-المقصر-في-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55516.mp3","categories":["الحقوق الزوجية","النفقات"]},{"id":14600,"question":"المستمع (ر. م. ش) من مصر، بعث برسالة طويلة يقول فيها: طلق والدي والدتي، وأنا جنين في بطنها، ثم كبرت وتزوجت، وأصبح عندي أولاد، وأنا أعيش مع والدتي، ولا أعرف والدي إلا بالاسم، لم يقم بالصرف علي أو تعليمي أو الاهتمام بي، وتزوج والدي من امرأة أخرى وأنجب منها أولادًا أصبحوا هم الذين يدبرون أعماله، ويتحكمون في مسئولياته، ولكنه في الآونة الأخيرة.الشيخ: أعد أعد.المقدم: يقول المستمع (ر.م.ش) من مصر، بعث برسالة يقول فيها: طلق والدي والدتي، وأنا في بطنها، ثم كبرت، وتزوجت وأصبح عندي أولاد، وأنا أعيش مع والدتي، ولا أعرف والدي إلا بالاسم، لم يقم بالصرف علي أو تعليمي، أو الاهتمام بي، وتزوج والدي من امرأة أخرى وأنجب منها أولادًا أصبحوا هم الذين يديرون أعماله، ويتحكمون في مسئولياته، ولكن في الآونة الأخيرة أصبح والدي يشتكيني لكل شخص في المدينة بأنني عاق، وبأنني أعمل في الخارج، ولا أبعث له نقودًا مع أنه غني.وسؤالي يا سماحة الشيخ: هل له الحق في أن أرسل له أي مبلغ من المال، والأمر بالصورة التي ذكرتها، ثم يستطرد في رسالته ويقول: والدتي غنية جدًا، حيث أنها تتاجر في الكثير من السلع، وليس لديها أولاد غيري، وتطلب مني أن أرسل لها نقودًا، مع أن حالتي المالية لا تسمح بذلك، حيث أن راتبي متواضع ومسئوليات الزوجة والأولاد كثيرة، هل يجب علي مع هذا أن أرسل لها نقودًا أم لا؟وإذا رفضت هل يدخل هذا في باب العقوق؟جزاكم الله خيرًا.","title":"حكم الإنفاق على الوالدين مع عدم الاستطاعة","answer":"الجواب: الواجب عليك -يا أخي- الحرص على بر والدك ووالدتك، ولو كان أبوك قصر في حقك، فالواجب عليك أن تحرص على بره، والإحسان إليه بالمكاتبة والكلام الطيب والزيارة إذا تيسرت، والأخذ بخاطره حتى لا يقع بينكما عقوق.  أما هو فالواجب عليه أن يعدل بينك وبين أولاده الآخرين؛ لأن الرسول  قال: اتقوا الله، واعدلوا بين أولادكم فإذا أعطاهم أعطاك، وساوى بينك وبينهم غير النفقة التي ينفقها عليهم النفقة العادية، إذا أعطاهم أشياء من أراضٍ أو سيارات أو غير ذلك، عليه أن يعدل بينكم، وأنت عليك أن تراعي خاطره بالكلام الطيب، والأسلوب الحسن والزيارة إذا أمكن؛ حتى لا يقع بينكما العقوق. أما أن تعطيهم من المال أو تعطي والدك من المال وأنت راتبك قليل ولا يكفي، وحده أن يكفيك وأسرتك وهما بخير، الوالد بخير، والوالدة بخير فلا يلزمك، لا يلزمك أن ترسل إليهما مالًا، ولكن تعتذر إليهما بالكلام الطيب، والأسلوب الحسن، وتقول: يا أبي، إن راتبي قليل، وأن مسئولياتي كثيرة، وأنه ما يحصل عندي فضل حتى أرسل إليك، وأنت -بحمد الله- في خير، وهكذا تقول للوالدة: أنت بحمد الله في خير، وأنا راتبي كذا وكذا، وأرجو مسامحتي، فتأخذ خاطرهما بالكلام الطيب، ولا يلزمك أن ترسل لهما مالًا، وهما غنيان، وأنت بحاجة إلى المال، لا يلزمك، لكن عالج الموضوع بالأسلوب الحسن، والكلام الطيب، والمكاتبة الحسنة حتى تكسب رضاهما، وفقك الله، ويسر أمرك. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13104/حكم-الانفاق-على-الوالدين-مع-عدم-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63603.mp3","categories":["النفقات","الهبة والعطية"]},{"id":14737,"question":"ما هي نفقة المتعة؟ وهل تحق لزوجتي؟ وكيف تقدر؟","title":"ما حكم نفقة متعة المطلقة؟ وكم مقدارها؟","answer":"الجواب: يستحب لك تمتيعها؛ لقول الله تعالى: وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ [البقرة:241] يستحب لك تمتيعها بما تيسر من المال: كسوة أو نقود، وليس لها حد محدود بما يسر الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13235/ما-حكم-نفقة-متعة-المطلقة-وكم-مقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63003.mp3","categories":["النفقات","بر الوالدين"]},{"id":14793,"question":"هل من كلمة للأزواج في معاملة الزوجات يا سماحة الشيخ؟","title":"نصيحة في حسن تعامل الزوج مع زوجته","answer":"الجواب: نعم، نصيحتي للأزواج أن يتقوا الله، نصيحتي لجميع الأزواج أن يتقوا الله في نسائهم، وأن يعاملوهن باللطف، والمعاملة الطيبة، كما قال الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] بالكلام الطيب، بالأسلوب الحسن، بالحلم، بالخلق الكريم، بأداء حقوقهن كاملة، هذا الواجب على جميع الأزواج، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] مثل ما أنك تحب أن تعاشر بالمعروف، وأن تكون طيبة معك في أخلاقها وسيرتها أنت كذلك، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] كون حقك أكبر لك درجة زيادة لا يقتضي، هذه الدرجة ما تقتضي أنك تسيء إليها، وأنك تظلمها لا، يجب عليك أن تحسن الخلق، وأن تعاشر بالمعروف، وأن تقوم بالواجب، من جهة النفقة اللازمة بالمعروف، ومن جهة طيب الكلام، وحسن المخاطبة، هذا هو الواجب على الأزواج جميعًا أن يتقوا الله، وأن يحسنوا إلى أزواجهم بالكلام الطيب، والأسلوب الحسن، والسيرة الحميدة، وعدم السهر، وعدم التقتير في النفقة، كل هذا واجب. عليك أن تنفق بالمعروف، وعليك أن تحذر السهر الذي يضر زوجتك ويضرك، ويسبب أيضًا فساد دينك، فإن السهر شره عظيم، قد تضيع معه صلاة الفريضة، قد يكون مع أناس من أهل الشر يضرونك ويجرونك إلى أنواع الفساد، فاحذر. الرسول ﷺ نهى عن السمر بعد العشاء، فالسنة أن تأتي إلى بيتك بعد العشاء، وأن تنام مع أهلك، تستريح في بيتك، تدع السهر بعد العشاء. ويجب على الرجل أن يحذر صحبة الأشرار، صحبة الأشرار شرها عظيم، فالواجب الحذر من صحبة الأشرار، والواجب العناية بصحبة الأخيار، وعدم السهر، والعناية بالصلوات الخمس، والمحافظة عليها في الجماعة، وحسن الخلق مع الزوجة، وطيب الكلام مع الزوجة، هكذا، كما قال ﷺ: خياركم خياركم لنسائهم والله يقول وهو أعظم: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] ويقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13285/نصيحة-في-حسن-تعامل-الزوج-مع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56116.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":14944,"question":"وهذه رسالة المستمع (س. ق. ع) يقول: رجل أراد السفر لطلب العلم، وله أهل من الزوجة والأولاد، وشاور مع زوجته في طلاقها، وعدم نفقتها، وقالت: لا تطلقني، وقد عفوت عن نفقتي وخلافه، فهل تبقى بدون نفقة ولا يضره شيء أم لا؟","title":"حكم تنازل المرأة عن النفقة مقابل عدم طلاقها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالحق للمرأة لا لغيرها، فإذا سمحت عن نفقتها فلا حرج، ويجوز للزوج إبقاؤها في عصمته من دون أن ينفق عليها إذا سمحت، ومتى عادت وطلبت النفقة فإنه يخير، إما أن ينفق، وإما أن يطلق، نعم.","link":"https://binbaz.org.sa/fatwas/13440/حكم-تنازل-المراة-عن-النفقة-مقابل-عدم-طلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64901.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":15131,"question":"وردتنا رسالة من بيشة، بعث بها المرسل يحيى سعد مخيلي الشهراني، يقول: تزوجت فتاة، وكان عمرها سبعة عشر سنة، ثم بقيت عند أهلها سبعة عشر سنة أخرى، وأنا لم أدخل بها، وأنها تحبني وأحبها، ولكن أهلها منعوها من الزواج الفعلي، أي: الدخول بالمعنى المعروف، وأخيرًا طلقتها، ثم خطبت زوجة أخرى، وحصل معها ما حصل مع الأولى، فهل أطلقها؟ أم أن هناك رأيًا للشرع آخر؟علمًا بأنني متزوج من امرأة، وعندي منها أطفال، وأنا أرغب في الزواج من الثانية، وفقكم الله.","title":"حكم منع الولي موليته من الدخول على زوجها بعد العقد","answer":"الجواب: الواجب على أولياء الزوجة أولياء المرأة وأهلها من أم وأخت وخالة ونحو ذلك، أن يساعدوا على الخير، وأن يشجعوا على الجمع بين الرجل وأهله، وأن لا يعطلوا المرأة عن زوجها، لا قبل العقد، ولا بعد العقد.  فإذا تم العقد فالواجب البدار بإدخالها على زوجها، وتمكينه منها؛ حتى يحصل المقصود بالنكاح من قضاء الوطر، وعفة الفرج، وغض البصر، ووجود النسل والذرية للجميع، هذا هو الواجب، ولا يجوز لأمها ولا لأبيها ولا لأوليائها تعطيلها من الزواج، ولا تعطيلها من دخولها على زوجها بعد العقد، هذا هو الواجب عليهم. وكثير من الناس -والعياذ بالله- لا يبالي بموليته، ولا يهتم منها، بل يعطلها كثيرًا؛ إما لخدمتها في بيته، وإما لرعيها غنمه، وإما لغضبه على أمها، أو غضبه عليها لأسباب صار ذلك؛ فيظلمها، ويتعدى عليها، ويحبسها عن الزواج لما في نفسه من الشر عليها، أو على أمها، أو على إخوتها الخاصين بها، أو نحو ذلك، وهذا ظلم وعدوان لا يجوز، بل الواجب عليه أن يتقي الله، وأن يبادر بتزويج موليته، سواء كان أخاها، أو أباها أو عمها، وأن لا يعطلها، ثم إذا تم العقد فالواجب أيضًا أن لا يعطلها، بل عليه -الولي- أن يبادر بإدخالها على زوجها، أو إدخاله عليها إن كان الدخول عليها في بيتهم، أما التعطيل فهو منكر، وهذا واقع في كثير من الناس، يعطلون بناتهم وأخواتهم لأسباب خبيثة ظالمة، إما لتخدم بيته، وتخدم زوجته، أو لتخدمه في رعي غنمه، أو لأسباب أخرى، وهذا لا شك أنه منكر وحرام عليه، وإثم وظلم. وبعد العقد كذلك لا يجوز تعطيلها أيضًا، بل يجب البدار بإدخالها على زوجها، وتمكينه منها، حتى يحصل المقصود من النكاح، والله يقول -جل وعلا-: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19] فالظلم قبيح، وشره عظيم، ويقول ﷺ: اتقوا الظلم، فإن الظلم ظلمات يوم القيامة وحبس النساء عن الزواج -سواء كن بنات أو أخوات أو غيرهن- ظلم وعدوان، وهكذا حبسهن بعد العقد، وعدم إدخالهن على أزواجهن ظلم وعدوان.  فأرجو ممن يسمع كلامي هذا أن يبلغه غيره، وأن ينصح من يعلم منه هذا العمل الخبيث هذا المنكر؛ فينصحه لله، ويحرضه على تزويج موليته، وعدم حبسها ظلمًا وعدوانًا. وعلى ولاة الأمور إذا علموا ذلك أن يعاقبوا من فعل هذا، على القضاة والأمراء وولاة الأمور جميعًا عليهم أن يعاقبوا من عرف بهذا الظلم لموليته؛ فإنه يستحق العقاب ردعًا له ولأمثاله عن هذا الظلم، والقاضي أخص بهذا؛ فإنه يعلم من هذه الأمور ما لا يعلمه غيره، فالواجب على القضاة أن يهتموا بهذا، وأن يحكموا بتعزير وتأديب من يعرف بهذا الأمر رجاء السلامة من هذا الظلم لهؤلاء النساء، نعم، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13632/حكم-منع-الولي-موليته-من-الدخول-على-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65704.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":15270,"question":"هل من كلمة -يا سماحة الشيخ- لهؤلاء الأزواج الذين تلزمهم النفقة على زوجاتهم وأولادهم؟","title":"نصيحة لمن يهملون النفقة على زوجاتهم وأبنائهم","answer":"الجواب: نعم، الواجب على كل زوج أن ينفق على زوجته، وعلى أولاده، وأن يتقي الله في ذلك، إلا إذا كان عندها مال، وسمحت فلا بأس، وإلا فالواجب عليه أن يتقي الله، وأن يراقب الله، وأن ينفق عليها، وعلى أولادها نفقة مثلها، هذا هو الواجب، قال النبي ﷺ في الأزواج: وعليهم رزقهن وكسوتهن بالمعروف على الزوج كسوة الزوجة بالمعروف، يكسو أولاده، وقال تعالى: وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233]. فالواجب على الزوج أن يتقي الله، وأن ينفق على الزوجة، وعلى الأولاد النفقة التي تنفق على أمثالهم، يعني: النفقة التي تناسب مثلهم، لا إسراف، ولا تقتير، إلا إذا كانت امرأة غنية وسامحته، وأنفقت على نفسها فلا حرج.","link":"https://binbaz.org.sa/fatwas/13770/نصيحة-لمن-يهملون-النفقة-على-زوجاتهم-وابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56515.mp3","categories":["النفقات","بر الوالدين"]},{"id":15696,"question":"من أسئلة السائل إبراهيم من الرياض، يقول: ما هي حقوق الأبناء على الآباء؟جزاكم الله خيرًا.","title":"حقوق الأبناء على آبائهم","answer":"الجواب: حق الولد على أبيه أن ينفق عليه، مادام صغيرًا، ومادام عاجزًا عن النفقة، ينفق عليه أبوه إذا استطاع، ويؤدبه، ويعلمه ما أوجب الله عليه، وينهاه عما حرم الله عليه، ويكون قدوةً له في الخير، بفعله وقوله.  هكذا يجب على الآباء أن يتقوا الله، وأن يكونوا قدوةً صالحة لأولادهم، وأن يعلموهم، ويوجهوهم إلى الخير، ويؤدبوهم إذا خالفوا الشرع، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع. وإذا كان الولد فقيرًا -والأب غنيًا- وجب عليه أن ينفق عليه، وإن كان كبيرًا، ينفق عليه حتى يوسع الله عليه، ويجد عملًا يستطيع النفقة منه، وأهم شيء العناية بدينه، كونه يعتني بدينه، يوجهه إلى الخير، يأمره بطاعة الله، ينهاه عن محارم الله، يأمره بالصلاة، يأمره بكل ما أمر الله به ورسوله، وينهاه عن كل ما نهى الله عنه ورسوله، ويكون قدوةً أيضًا في أفعاله، يكون الأب قدوة، والأم تكون قدوة في أفعالهما وأقوالهما الطيبة، قدوةً لأولادهما. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14253/حقوق-الابناء-على-اباىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57305.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":15759,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية محافظة المنيا، وباعث الرسالة المستمع خالد طلعت عبدالله علي، الأخ خالد يقول في رسالته: لرجل ابنان متزوجان، وكلاهما يعول أسرة، أحد هذين الابنين حالته ميسرة، والآخر نفقاته كثيرة، ويحتاج إلى بعض العون، فقام الأب بتخصيص دخل ثابت لابنه المحتاج هذا برغبة الوالد، ودون طلب من ابنه هذا، إلا أن الابن الآخر ثار على والده وأخيه، واعتبر أن أباه يفضل أخاه عليه. و هل هذا جائز شرعًا؟ علمًا بأن الابن ينتفع بهبة والده له في حياته فقط.جزاكم الله خيرًا.","title":"حكم إنفاق الأب على الابن الفقير دون الغني","answer":"الجواب: إذا كان أحد الابنين فقيرًا، وليس عنده أسباب تقوم بحاله، فعلى الوالد أن ينفق عليه إذا كان قادرًا، والابن الغني لا حق له في ذلك، فإذا كان عنده أولاد بعضهم فقراء، وبعضهم أغنياء، والوالد يقدر على النفقة، وجب عليه الإنفاق على الفقراء، وإن كانوا كبارًا، إذا لم يكن عندهم أسباب تغنيهم، ولا كسب يغنيهم؛ لأن النفقة أمر لازم على الوالد أن ينفق على ولده الفقير. أما إذا كانوا كلهم أغنياء، فليس له أن يخص أحدًا بالعطية؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فالواجب أن يعدل إن كانوا فقراء، أنفق عليهم، وأعدل فيهم، وإن كانوا أغنياء أعدل فيهم أيضًا، أعطاهم جميعًا، أو تركهم جميعًا، أما إذا كان أحدهم فقيرًا، والبقية أغنياء، أو أكثرهم فقراء، وبعضهم أغنياء، فإنه ينفق على الفقير، وليس هذا بظلم، بل واجب عليه أن ينفق إذا كان الفقير ما عنده أسباب، ما عنده كسب، لا يستطيع الكسب، فإن الوالد إذا كان قادرًا عليه ينفق عليه ويواسيه بنفقة أمثاله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14346/حكم-انفاق-الاب-على-الابن-الفقير-دون-الغني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74106.mp3","categories":["الهبة والعطية","النفقات","بر الوالدين"]},{"id":15776,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (ب. م. ح) من جمهورية مصر العربية، أخونا سأل في حلقة مضت بعض الأسئلة، وفي هذه الحلقة يسأل ويقول: إنني منفصل عن والدي، ولي بيت مستقل، وأبي له حانوت يحتوي على بعض البضائع، وتعطيني والدتي من ذلك الحانوت دون علم والدي، فهل ما آخذه يعتبر حلالًا أم لا يجوز؟جزاكم الله خيرًا.","title":"حكم إعطاء الأم ابنها من مال أبيه دون علمه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن كنت فقيرًا لا تستطيع الكسب، وليس عندك ما يقوم بحالك فلا حرج، إذا كان ما تعطيك والدتك من الحانوت لا يضر والدك فلا بأس؛ لأن عليه أن ينفق عليك، كما تأخذ الزوجة من مال زوجها حاجتها، وإن لم يرض، وإن لم يعلم؛ لأن عليه أن ينفق عليها، أما إن كنت في غنى وفي سعة فليس لك أن تقبل ذلك إلا بإذن والدك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14364/حكم-اعطاء-الام-ابنها-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74201.mp3","categories":["النفقات","بر الوالدين"]},{"id":16034,"question":"تقول: أنا فتاة أعيش مع أمي وأبي وأخي، مع العلم أن جميع إخوتي وأخواتي قد تزوجوا، وأقوم أنا بالإنفاق على أهلي، فهل تلزمني النفقة عليهم؟ وإذا امتنعت عن ذلك أكون آثمة، والعياذ بالله؟","title":"حكم إنفاق الأبناء على الآباء والإخوة","answer":"الجواب: إذا كنت قادرة، عندك مال، سواء من طريق الوظيفة، أو غيرها، وأبوك عاجز، وأمك عاجزة، وأخوك عاجز؛ وجب عليك الإنفاق، وهذا من صلة الرحم، ومن بر الوالدين، بشرطين: أحدهما: أن تكوني قادرة عندك مال. والشرط الثاني: أن يكونوا فقراء عاجزين. أما إذا كنت عاجزة؛ فلا يكلف الله نفسًا إلا وسعها، أو كانوا أغنياء؛ فإنه لا يلزمك النفقة عليهم، وأبشري بالخير في الإنفاق عليهم إذا أحسنت وصبرت، ولو كانوا أغنياء فهذا بر عظيم، وخير كبير، ولكن لا يلزمك إلا بالشرطين: قدرتك وعجزهم، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14666/حكم-انفاق-الابناء-على-الاباء-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74804.mp3","categories":["النفقات","بر الوالدين"]},{"id":16100,"question":"السائلة تقول: هل من الواجب على الزوج النفقة على زوجته في الفترة التي تقضيها في منزل والدها عندما يقوم بتأثيث منزلهم الجديد -أي: في فترة الملكة قبل الزواج- لأن والدي يقول: يجب على زوجك النفقة عليك من يوم الملكة، وإن هذا واجب عليه؟","title":"حكم النفقة على المعقود عليها قبل الدخول بها","answer":"الجواب: هذا فيه تفصيل: إن كان هو تزوجها، وقال: خلوها عندكم عليه النفقة، أما إذا كان أهلها، أو هي طلبت البقاء عند أهلها لحاجاتهم؛ فلا نفقة عليه حتى تصل إليه، أما إذا أبقاها عندهم لمصلحة رآها هو؛ هذا ينفق عليها، نعم.","link":"https://binbaz.org.sa/fatwas/14743/حكم-النفقة-على-المعقود-عليها-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57920.mp3","categories":["النفقات","بر الوالدين"]},{"id":16656,"question":"من أسئلتها أيضًا يا سماحة الشيخ تقول: شخص أخذ من مال أبيه دون علمه لضرورة دعته إلى ذلك العمل، ثم رد هذا المبلغ بعد فترة من الزمن، من غير علمه أيضًا، ما حكم ما فعله؟ مأجورين.","title":"حكم أخْذ الابن من مال أبيه دون علمه ثم إرجاعه","answer":"الجواب:  الواجب ألا يأخذ من ماله إلا بإذنه، إلا إذا كان قصر في النفقة، إذا كان أبوه هو الذي ينفق عليه، وهو عاجز، ما عنده شيء، وأبوه هو الذي ينفق عليه، له أن يأخذ من ماله ما يحتاجه في النفقة من غير إسراف، من طعام، أو نقود للكسوة، من غير إسراف، إذا كان والده بخيلًا، يقصر؛ فله أن يأخذ ما يكمل النفقة، أما أن يأخذ أموالًا زيادة على هذا لتجارته، أو لأسباب أخرى لا، ليس له أن يأخذ، لا يأخذ إلا بإذن؛ لأن أموال الغير محرمة على نفسه، يقول النبي ﷺ: كل المسلم على المسلم حرام: دمه، وماله، وعرضه. ليس للإنسان أن يأخذ من مال أخيه إلا بحق، ولو زعم أنه سيرده، ولو أنه على سبيل القرض، إلا بإذنه، لكن إذا كان ذلك يتعلق بطعامه، وشرابه، وكسوته؛ لأن أباه كان يقصر في سد حاجته، فله أن يأخذ بقدر حاجته، في ملبسه، ومأكله، ومشربه. والزوجة لها أن تأخذ إذا قصر عليها، لها أن تأخذ قدر حاجتها من دون زيادة، والدليل على هذا ما ثبت في الصحيحين، عن هند بنت عتبة بن ربيعة زوجة أبي سفيان بن حرب أنها قالت: \"يا رسول الله! إن أبا سفيان رجل شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل علي من جناح إن أخذت من ماله بغير علمه؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك، ويكفي بنيك يعني: ولو بغير علمه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15389/حكم-اخذ-الابن-من-مال-ابيه-دون-علمه-ثم-ارجاعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58313.mp3","categories":["النفقات","بر الوالدين"]},{"id":17049,"question":"تقول السائلة يا سماحة الشيخ: تزوجت وأنا صغيرة، ولم أكن أعرف حقوق الزوج، وغرر بي أحدهم حيث تطلقت من زوجي، وظلمت زوجي، وأنا الآن نادمة، فماذا يلزمني حفظكم الله؟ وأرجو يا سماحة الشيخ أن تدعو له بالخير، وبتيسير الرزق، وأنا أتمنى العودة له، فما توجيهكم حفظكم الله؟","title":"الحث على إحسان معاملة المرأة لزوجها","answer":"الجواب: التوجيه أن عليك التوبة إلى الله مما فعلت من التقصير، الندم والتوبة إلى الله، وسؤاله المغفرة  وعدم العودة إلى مثل ذلك مع الزوج الجديد، وإذا عدت إليه إن كان الطلاق طلقة واحدة، أو طلقتين له العود إليك، وعليك الجد في إحسان المعاشرة إذا عدت إليه بالكلام الطيب والأسلوب الحسن، والسمع، والطاعة في المعروف، وعدم المعاكسة، هكذا ينبغي للزوجة، الله يقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول ﷺ: استوصوا بالنساء خيرًا.  ويقول في حق النساء: على المرأة ألا تأذن في بيت زوجها إلا بإذنه، ولا يطأ فراشها أحد إلا بإذنه وعليها السمع والطاعة لزوجها في المعروف، فعلى المرأة السمع والطاعة لزوجها في المعروف، والعناية بإكرامه، والإحسان إليه؛ لأن حقه عليها أكبر وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]. وهو عليه أن يستوصي بها خيرًا، وألا يظلمها، وأن يحسن عشرتها، لكن حقه عليها أكبر، فعليها أن تسمع وتطيع في المعروف، وأن تعينه في أمور بيته، وأن تكرمه حتى تستقيم الحال بينها وبينه، لكن لا تطيعه في المعاصي، إنما تكرمه في لباسه، وفي فراشه، وفي تمكينه من نفسها إذا أرادها، وفي غير هذا من شؤون البيت، ومع أولاده وأهل بيته، ووالديه، ونحو ذلك، يكون لها سيرة حسنة معه، ومع والديه، ومع أقاربه حتى تشكر، ويدعى لها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15838/الحث-على-احسان-معاملة-المراة-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58724.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17071,"question":"تقول السائلة: بأن زوجها شحيح لا يعطيها ما يكفيها وأولادها من مصاريف البيت، وأدوات المدرسة.. وغير ذلك، هل يحل لها أن تأخذ من ماله بدون علمه؟","title":"حكم أخذ المرأة من مال زوجها البخيل","answer":"الجواب: نعم، إذا كان يقصر في نفقة البيت لها أن تأخذ من ماله بغير علمه، إذا قصر في نفقتها ونفقة أولاده منها لها أن تأخذ بالمعروف من غير إسراف، ولا تبذير، لكن بالمعروف؛ لأن هند بنت عتبة امرأة أبي سفيان -رضي الله عنهما- قالت: «يا رسول الله، إن أبا سفيان رجلٌ شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل آخذ من ماله ما يكفيني؟ قال: نعم. خذي من ماله بالمعروف ما يكفيك، ويكفي بنيك خذي من ماله بالمعروف يعني: من غير إسراف، ولا تبذير. نعم. المقدم: إذًا يا سماحة الشيخ بعض الأخوات يقلن: هل النفقة محددة مثلًا أو معينة؟ الجواب: غير محددة حسب الحاجة، تختلف بحسب الغلاء والرخص، حسب حاجة الأولاد، وكثرتهم، وقلتهم، حسب الحاجة ... الوسط، مثلما قال الله -جل وعلا- في عباده الصالحين: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا [الفرقان:67] وقال -جل وعلا-: وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [الإسراء:29] المغلولة: البخيل، والبسط كل البسط: هذا المسرف، المبذر. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15876/حكم-اخذ-المراة-من-مال-زوجها-البخيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58811.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17413,"question":"إذا غضبت الزوجة على زوجها فما الواجب أن تفعله في ذلك؟","title":"واجب المرأة تجاه زوجها","answer":"الجواب: الواجب عليها عدم العصيان لزوجها، وعدم المخالفة لأوامره الشرعية والمباحة، عليها السمع والطاعة لأوامره الشرعية والمباحة، وعليها كف الأذى. وهو كذلك عليه أيضًا كف الأذى عنها، وأن يعاملها بالحسنى، وأن يستوصي بها خيرًا، وعليهما التعاون على البر والتقوى، فإذا وجد ما يغضبها؛ فلا حرج عليها، إذا سبها، وغضبت؛ لا حرج، لكن عليها أن تجاهد نفسها، وعليها أن تنصحه عن السب والشتم، تقول له: اتق الله، هذا لا يجوز لك.. بالكلام الطيب. ولا شك أن الأذى منه يوجب غضبها، يسبب الغضب، لكن عليها أن تجتهد، وأن تتحمل، وأن تحرص على السمع والطاعة في المعروف، وأن تنصحه عما يقع منه من الغضب، والشتم، أو الضرب حتى تزول المشكلة بينهما مهما أمكن، فإن لم يفعل ذلك؛ فلها الخروج إلى بيت أهلها، والرفع إلى المحكمة.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16279/واجب-المراة-تجاه-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77114.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17432,"question":"من القصيم رسالة وقع صاحبها في نهايتها بالحرفين (م. م) يقول في رسالته: والدي متزوج من أربع نساء، وله أربعة عشر ولدًا وعشرون بنتًا، فمجموع الأولاد أربعة وثلاثون، والمشكلة كما يقول: إن أبي لا ينفق علينا إطلاقًا جميعًا بما في ذلك جدتي (والدته).. ثم يستمر في وصف والده فيقول: إنه غني غناء فاحشًا -كما يقول- ويملك عقارات كثيرة، وبنى ستة مساجد بتكلفة أربعة ملايين ريال تقريبًا، وهو يزكي، ويصلي، ويتصدق كثيرًا، ويساعد المحتاجين، ولكنه معنا على العكس من الآخرين، وعندما ناقشته؛ برر تصرفه بقوله: عندما أموت سوف تنسونني .. ويستمر في رسالته على هذا المنوال، ويرجو من سماحتكم التوجيه له، ولإخوته، ولوالده.","title":"توجيه لمن يكثر التصدُّق ويقصر في نفقة أهله","answer":"الجواب: ما ذكرته عن والدك من الأعمال الطيبة يسر كل مسلم، فجزاه الله خيرًا، وتقبل منه أعماله الطيبة في تعمير المساجد، والصدقة على الفقراء، والمحاويج، أما ما يتعلق بنفقته على زوجاته، وأولاده فهذا غلط، لابد أن ينفق على زوجاته، بل يجب عليه أن ينفق على زوجاته، والله -جل وعلا- أوجب عليه ذلك، قال -جل وعلا-: وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233] يعني: الوالدات، يعني: الزوجات، وقال النبي ﷺ في الحديث الصحيح لما ذكر الزوجات قال: ولهن عليكم رزقهن، وكسوتهن بالمعروف. فالواجب عليه أن ينفق عليهن بالمعروف، هذا واجب عليه، وحق عليه، وكذلك أنتم إذا كنتم قاصرين فقراء؛ وجب عليه أن ينفق عليكم، على الذكور والإناث جميعًا، على الوالد أن ينفق على أولاده إذا كانوا محاويج. أما من كان فيكم غني، مستغني عن والده، عنده أسباب تقوم بحاله؛ فلا يلزم والده النفقة عليه، إنما ينفق على المحتاج، فإذا كان بعض البنات قد تزوج، واستغنى بالزوج، أو عندها مال، وعندها وظيفة، وهكذا الأولاد إذا كان عندهم وظائف، أو أكساب أخرى تغنيهم؛ فلا يلزمه أن ينفق عليهم. أما ما يتعلق بالورث فهذا الله هو الذي أعطاكم إياه، ما هو الذي أعطاكم هو، إذا مات وأنتم موجودون فلكم الورث أغنياء، أو فقراء، لكن عليه في الحياة أن يتقي الله، وأن يراقب الله سبحانه، فينفق على من يستحق النفقة منكم لفقره وحاجته، وعلى الزوجات أيضًا مطلقًا، ومن كان منكم غنيًا من ذكر وأنثى؛ فلا يلزمه ذلك، لا يلزمه الإنفاق عليه؛ لأنه مستغنٍ بما أعطاه الله من المال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16307/توجيه-لمن-يكثر-التصدق-ويقصر-في-نفقة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83610.mp3","categories":["النفقات","بر الوالدين"]},{"id":17435,"question":"سماحة الشيخ، أمامي رسالة مكونة من صفحتين، لا أدري هل أقرأ هاتين الصفحتين؟ أم أقرأ ما لخصته عنها؟الشيخ: الملخص يكفي.المقدم: ملخص ما في هذه الرسالة: أن صاحبها يشكو من زوجته شكوى فيها كثير من المرارة، فهو يقول: إنها تصر على الذهاب لأهلها في كل أسبوع، ثم إنها تدفع الراتب كاملًا إلى أهلها، مع العلم أنه هو الذي يذهب بها إلى المدرسة، ويعيدها أيضًا إلى المدرسة، وهي تترك البيت كثيرًا في سبيل هذه الوظيفة، ثم يقول: إنها تهمل رعاية البيت، والطفل، وتترك كل ذلك للخادمة، وهي كثيرة الذهاب والإياب إلى الناس، ويرجو من سماحتكم التوجيه؟ جزاكم الله خيرًا.","title":"نصيحة لمن تؤذي زوجها ولا تطيعه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، سيد ولد آدم، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد.  فإن الواجب على كل زوجة أن تسمع، وتطيع لزوجها في المعروف، وليس لها أن تذهب إلى أهلها إلا بإذنه، ولا إلى غير أهلها إلا بإذنه، وهكذا التدريس ليس لها أن تدرس إلا بإذنه إلا أن يكون قد شرط عليه عند العقد، فـ المسلمون على شروطهم وإلا فليس لها أن تدرس إلا بإذنه. وكونها تذهب إلى أهلها كل أسبوع ليس لها ذلك إلا بإذنك، فينبغي لك أن تلاحظ الموضوع، وأن تنظر في المصلحة، فإن رأيت أن في ذهابها مصلحة؛ فلا بأس مراعاة لخاطر والديها، وحرصًا على سلامة القلوب، وبقاء المودة، وإن تيسر أن يكون ذهابها إليهم في أكثر من ذلك، كعشرة أيام، أو نصف شهر، فلا بأس، تتفق أنت والوالدان، والمرأة على الشيء الذي فيه المصلحة للجميع، وفيه كسب رضاك، وعدم التسبب في الفراق. وهكذا ليس لها الخروج لغير أهلها إلا بإذنك، والواجب عليها أن تلزم البيت، وتعتني بالأولاد، وتربيتهم التربية الطيبة، ولا ينبغي أن تكلهم إلى الخادمة، بل ينبغي أن تعتني بهم هي، وأن تجتهد في تربيتهم، والإحسان إليهم، وإذا كانوا يفهمون تحرص على تربيتهم التربية الإسلامية، وتوجيههم إلى الخير. أما الراتب فهو لها، لكن ينبغي لها أن تعطيك بعض الشيء في مقابل تعبك، وذهابك، وإيابك، وتسميحًا لخاطرك ولا سيما إذا كنت محتاجًا، فإن المشروع لها أن تساعدك؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه فنصيحتي لها أن تساعدك من الراتب، والواجب عليها أن تسمع، وتطيع لك في كل شيء، ليس فيه معصية لله  لا في ذهابها إلى أهلها، ولا في غيرهم. أما وجود الخادمة لديكم فأنت قد أخطأت في الإتيان بالخادمة، هي التي سببت هذه المشاكل، أبعد الخادمة حتى تقيم في البيت هي، وتقوم بأولادها، وخدمة البيت، فإبعاد الخادمة هو الطريق إلى ... السلامة من ذهابها إلى أهلها، وغيرهم في كل وقت، ثم الخادمة وجودها عندك فيه خطر عليك، وعلى دينك، وليس في البيت غيرها، والرسول ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فوجودها في البيت، والمرأة خارج البيت في الدرس، أو عند أهلها فيه خطر عظيم.  فنصيحتي لك إبعاد الخادمة، وردها إلى أهلها، وأن تقوم الزوجة بما يتعلق بالبيت، ولو تركت التدريس، هذه نصيحتي لكما جميعًا، ونسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا الأولى في هذه الأمور الحياة الزوجية؟ الشيخ: نعم، على كل منهما العناية بالحياة الزوجية، والحرص على بقائها على الوجه الشرعي من دون معصية لله . فالمقصود: أن المشروع لك أيها الأخ أن تعتني بحفظ زوجتك، وبقائها في البيت، وأن تعمل كل الأسباب التي تبعدها عن الخروج إلا بإذنك. المقدم: جزاكم الله خيرًا، لعل هذه الرسالة تتيح لنا الفرصة سماحة الشيخ كي ما نسأل: إذا ما أراد الإنسان أن يتزوج من موظفة، فما هي الشروط التي تنصحونه أن يشترطها حتى تكون الحياة الزوجية مستقيمة؟ الشيخ: هو يعمل بالأصلح، إن رأى الموافقة على بقائها في الوظيفة؛ فلا بأس، وإن رأى اشتراط ترك الوظيفة: فلا بأس، هو أعلم بنفسه، وهذا شيء يرجع إلى علمه، وإلى حاجته، وإلى تقديره، فإذا تيسر بقاؤها في الوظيفة الطيبة، وفي البيت من يقوم مقامها في إصلاح البيت، كأمه، وأخواته، ونحو ذلك، وإلا فالأصلح ألا يقبل موظفة، بل يتزوج امرأة غير موظفة؛ حتى تقيم في بيته، وحتى تعتني بالبيت، وحتى يرتاح إليها، إذا جاء من عمله وجدها. والمقصود بكل حال: هو أن ينظر فيما هو أصلح له في دينه، ودنياه مع الموظفة، وغيرها. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/16296/نصيحة-لمن-توذي-زوجها-ولا-تطيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83601.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17461,"question":"تقول السائلة: والدي متزوج من امرأة ثانية منذ أكثر من عشر سنوات، وهو لا ينفق على أمي، ولا على إخوتي، وإنما ينفق على زوجته الأخرى، وأولادها الذين هم إخوتي من أبي بحجة أنه لا يستطيع النفقة على أمي وإخوتي، والحجة بأن إخوتي قد توظفوا ولهم رواتب، مع العلم أن منهم من لم يزل طالبًا، ويأخذ المصروف من أخته الموظفة، ومن أخيه الموظف، فما الحكم؟ تقول: إن والدي يطلب من إخوتي أن يعطوه من رواتبهم، ويغضب إذا لم يعطوه، مع أن والدي موظف، ويتقاضى راتبًا شهريًا، لكن هو يقول: بأنه مديون، وعليه ديون كثيرة، لكن الله أعلم، على العموم إذا كانت الحالة كما ذكرت لكم فهل لي أن أدفع زكاة أموالي لوالدي؟ أفتوني مأجورين.","title":"حكم ترك الزوج النفقة على الزوجة الأولى","answer":"الجواب: يلزم الوالد النفقة على زوجته الأولى إذا كان أولادها لا يقومون بها، أما إذا كان أولادها يكفونها المؤونة، وقد أنفقوا عليها كفوا؛ لأن أولاده له، حقه عليهم كبير، والرسول ﷺ يقول: أنت ومالك لأبيك فإذا كفوه مؤونة أمهم، وأنفقوا عليها؛ كفى والحمد لله، أما إذا لم يكفوه، وهي تطلب النفقة مخيرة، إن شاءت صبرت، وإن شاءت قالت: طلقني، تطلب الطلاق إن لم تصبر، وإلا صبرت، وإن أنفق عليها أولاده كفوه المؤونة، والحمد لله، ولا حرج عليه. وإن طلب منهم شيئًا فعليهم أن يعطوه من مالهم ما لا يضرهم، أما إذا كان يضرهم، ولا يستطيعون؛ فلا يلزمهم ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن ما داموا يستطيعون؛ فعليهم أن يرضوه، ويعطوه من رواتبهم ما يعينه على قضاء دينه، وعلى النفقة على زوجته الجديدة، يقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم ويقول ﷺ: أنت ومالك لأبيك حق الوالد عظيم.  فالواجب عليهم أن يجتهدوا في إرضائه وفي مساعدته، ويقوموا بأمهم، وإذا كانت أمهم لا تصبر، وتقول: أبي النفقة من الزوج، تخيره تقول، تطلب الطلاق، إلا إذا قام أولاده بالنفقة فلا حق لها؛ لأن نفقة أولاده كنفقته، إذا أنفقوا عليها بما يكفيها الحمد لله، أما إذا ما أنفقوا عليها، ولا أنفق هو؛ فلها طلب الطلاق، نعم. المقدم: العدل بين الزوجات أمر مطلوب، هل لكم في ختام هذا ... ؟ الشيخ: العدل واجب، لكن إذا كان أولادها ينفقون عليها هم يقومون مقامه، والحمد لله ما يسمى جائرًا، أولاده يقومون مقامه في النفقة عليها، لكن عليه أن يقسم لها مثلما يقسم لضرتها، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16329/حكم-ترك-الزوج-النفقة-على-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77217.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17562,"question":"السائل الذي رمز لاسمه (ب. ف. ق) من الرياض يذكر بأنه شاب منَّ الله عليه بالهداية فيحمد الله على هذه النعمة ويسأل ويقول: فضيلة الشيخ! كنت فيما سبق آخذ من حرز أبي مبالغ كثيرة من المال دون علمه، وكان أخذي لها مستمر، وهي كثيرة جدًا لا أستطيع أن أرجعها إلى أبي، وأخشى إن أخبرته أن يغضب عليَّ، أو أن يفقد هذه الثقة الذي أولاها بي، ما الحكم يا فضيلة الشيخ إن أخذت مرة أخرى من مال أبي لتسديد إجار شقة أسكن فيها للدراسة؟ حيث أنني طالب ومكافأة الجامعة لا أستطيع القيام بها لجميع حقوقي، مع العلم بأنني أخشى إن طلبت من أبي أن يرفض ويغضب عليَّ؟","title":"حكم أخذ الابن من مال أبيه دون علمه","answer":"الجواب: لا يجوز لك أن تأخذ من مال أبيك بغير علمه، الواجب عليك أن تسأله، وأن تستأذن في ذلك إلا إذا كنت تأكل في بيته وقصر في نفقتك تأخذ بقدر الحاجة ككسوتك وأكلك إذا كان قصر، كما أذن النبي ﷺ لزوجة أبي سفيان هند أن تأخذ من ماله بالمعروف ما يكفيها ويكفي أولادها، فإذا كنت في نفقته وفي بيته، وقصر عليك، وليس عندك قدرة على التمام تأخذ من ماله بالمعروف حاجتك في لباس ونحو ذلك.. أما الأموال التي أخذتها زائدة على هذا فالواجب عليك ردها ولو بغير علمه، عليك أن تردها في ماله ولو بغير علمه، وإن استأذنته، وخبّرته، واستسمحته، ورددتها؛ فلا بأس، وإذا كنت تخشى أن يغضب ردها في ماله ولو بغير علمه. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16479/حكم-اخذ-الابن-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77519.mp3","categories":["النفقات","بر الوالدين"]},{"id":17720,"question":"هذه أخت مستمعة لهذا البرنامج تقول: أود من سماحة الشيخ أن يقدم نصيحة لزوجي، فزوجها تقول: مع أنه ملتزم بشعائر الدين ومؤدي للصلوات ومن الذين يخافون الله، إلا أنه يعاملها بقسوة مع أنها تقول: أنا وإياه نؤدي العبادات في أوقاتها وأولادنا- والحمد لله- على عبادة دائمة، هل من نصيحة سماحة الشيخ؟","title":"وصية للأزواج بحسن العشرة مع زوجاتهم","answer":"الجواب: نعم، نوصي جميع الأزواج بتقوى الله، والرفق بالزوجات، وإحسان العشرة، وعدم الغلظة وعدم سوء الكلام، قال الله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وقال جل وعلا: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228]، وقال النبي ﷺ: استوصوا بالنساء خيرًا.\nفالواجب على الأزواج المعاشرة الطيبة والكلام الطيب والأسلوب مع الزوجة الطيب وعدم الشدة وعدم العنف؛ لا في الكلام، ولا في غيره. هذا هو الواجب على الأزواج. والزوجة كذلك عليها أن تعامل زوجها بالكلام الطيب والأسلوب الحسن والسمع والطاعة في المعروف، كل منهما عليه أن يعين الآخر على الخير، الله يقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فعليها وعلى زوجها التعاون على البر والتقوى بالكلام الطيب والأسلوب الحسن والمسارعة إلى كل ما يرضي الآخر مما أباح الله، نسأل الله للجميع الهداية.\nالمقدم: أحسن الله إليكم وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16673/وصية-للازواج-بحسن-العشرة-مع-زوجاتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59527.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17904,"question":"رسالة من أحد الإخوة المستمعين يقول: أنا أعمل في المملكة العربية السعودية في بقالة صغيرة الحجم تكسب في اليوم مبلغًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة؛ لأن لدي أخوين بالإضافة إلى أسرتي فأحد إخواني الكبار رفض أن يساعدني لمد الأسرة فما هو رأيكم جزاكم الله خيرًا؟الشيخ: أعد. يقول: أنا أعمل في المملكة في بقالة صغيرة الحجم تكسب في اليوم مكسبًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة، ولدي أخوان بالإضافة إلى أسرتي لكن أحد إخوتي رفض أن يساعدني في مصاريف الوالدين فما هو توجيهكم لي ولإخوتي؟ جزاكم الله خيرًا.","title":"وجوب النفقة على الوالدين","answer":"الجواب: عليك أن تصرف على الوالدين والأولاد إذا كان الوالدان عاجزين لا يستطيعان الكسب والنفقة على أنفسهما من مالهما فتقسم ما لديك وما تحصل بين الجميع حسب طاقتك بين أولادك وأبويك ونفسك وزوجتك حسب الطاقة، وعلى أخويك أن يساعدا في ذلك، يلزمهما أن يساعدا في نفقة والديهما إذا كانا يستطيعان ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ونفقة أولادك وأبويك إذا كانا عاجزين عليك وهكذا زوجتك، وعلى أخويك أن يساعدا إذا كانا يستطيعان من مالهما أو من كسبهما وهذا واجب، هذا من بر الوالدين الواجب على الأولاد، ويكون التوزيع على حسب الطاقة، توزيع ما لديك يصنع به الطعام للجميع وتشتري كسوة للجميع حسب طاقتك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيرًا، يسأل عن أخيه الذي لم يساعده في الصرف على الوالدين؟\nالشيخ: إن شاء رفع أمره إلى الحاكم وإن شاء صبر، إن شاء رفعت أمره إلى الحاكم حتى يُلزمه إذا كان يستطيع، أما إذا كان عاجزًا فليس لك العدوان عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16927/وجوب-النفقة-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84606.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17958,"question":"هذه السائلة من جدة أختكم رمزت لاسمها بـ (أ. أ. ع) تقول: سماحة الشيخ! هل يحق للمرأة أن تأخذ من مال زوجها دون أن يعلم؟ علمًا بأن زوجها لا يعطيها ما يكفيها، وهي قد تكون محتاجة لذلك المال كي تشتري لها أشياء، لها ولأطفالها، أو تعطي والدتها، علمًا بأن هذا الزوج لا يشتري لها ولأطفالها إلا في عيد الفطر فقط، وعندما يسأل: من أين لك هذا الشيء؟ تقول له: من أمي، أو من أختي، فهل هذا جائز؟","title":"حكم أخذ المرأة من مال زوجها دون علمه","answer":"الجواب: نعم، إذا كان الزوج لا يقوم بالواجب لها أن تأخذ من ماله بالمعروف ما يكفيها وما يكفي أولادها، في الصحيحين عن عائشة رضي الله عنها أن هند بنت عتبة بن ربيعة زوجة أبي سفيان بن حرب، وأبو سفيان من سادات قريش ومن رؤساء قريش، اشتكت على النبي ﷺ بعد الفتح - بعد فتح مكة - اشتكت عليه وقالت: «يا رسول الله! إن أبا سفيان رجل شحيح لا يعطيني ما يكفيني ويكفي بني إلا ما أخذته من ماله بغير علمه فهل لي ذلك؟ فقال ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك يعني: ولو لم يعلم خذي من ماله بالمعروف ما هو بالإسراف والتبذير خذي من ماله بالمعروف ما يكفيك ويكفي بنيك. فإذا كان الزوج بخيلًا أو لا يبالي فللزوجة أن تأخذ من ماله بغير علمه ما يكفيها ويكفي أولادها بالمعروف، هذا لا حرج فيه.\nلكن لا تأخذ ما تعطي ... أمها وأباها لا. تأخذ ما يكفيها هي وأولادها وخدمها اللي في البيت بالمعروف، أما أن تأخذ شيئًا تعطيه الناس إلا برضاه إلا الشيء الذي جرت العادة به فضول الطعام، فضول الشراب، الشيء الذي جرت العادة بالصدقة به لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17001/حكم-اخذ-المراة-من-مال-زوجها-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78019.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":18025,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من حائل، باعثة الرسالة إحدى الأخوات المستمعات، الواقع تأثرت كثيرًا لهذه الرسالة إذ تقول فيها سماحة الشيخ:إنني فتاة ولي خمسة إخوة اثنان منهم متزوجون، وأنا أعمل معلمة، وإخواني هؤلاء البعض منهم يعمل والبعض يدرس، ووالدي يأخذ مني راتبي كله يعطيه إخوتي حيث يتصرفون فيه في عدة مجالات منهم من يشتري بها كتب، ومنهم من يشتري أشياء خاصة، ومنهم من تزوج بها، ومنهم من اشترى سيارة، ومنهم من يأخذ منها ليكمل بناء بيته، حيث أنني أعمل منذ سنوات عديدة، وكل أموالي تصرفوا بها ولم أعارض في ذلك، واحترامًا لوالدي وبرًا به وإحسانًا فأنا لا أريد إلا رضا الوالدين.سؤالي: هل يصح لوالدي أخذ أموالي هذه مع أنني أتعب كثيرًا لتحصيلها ليعطيها إخوتي وجهوني؟ جزاكم الله خيرًا.","title":"حكم أخذ الأب مرتب ابنته وإعطائه لأبنائه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد قال النبي الكريم عليه الصلاة والسلام في الحديث الصحيح: اتقوا الله واعدلوا بين أولادكم فوالدك له أن يأخذ من مرتبك ما يحتاجه في نفقته على بيته وأولاده القاصرين لقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم، وقوله ﷺ لرجل قال له: يا رسول الله! إن أبي اجتاح مالي، قال: أنت ومالك لأبيك. فلا حرج عليه أن يأخذ من مالك ومال غيرك من أولاده ما يحتاجه بشرط عدم الضرر عليك وعلى غيرك ممن يأخذ ماله، فيأخذ من مالك مالا يضرك ومن مال أولاده الآخرين ما لا يضرهم لحاجته في نفقته على نفسه وزوجته وأولاده القاصرين للحديثين السابقين. أما أن يأخذ مرتبك لأولاده الآخرين فهذا لا يجوز إلا برضاك إذا سمحت من نفس طيبة وأذنت له أن يتصرف في ذلك فلا حرج؛ لأن المال مالك فإذا سمحت فلا حرج وإلا فليس له ذلك، أما أن يأخذ المال منك لينفقه على نفسه وعلى أولاده القاصرين الذين تلزمه نفقتهم فهذا لا حرج عليه وليس بجائر، وإذا كنت في حاجة إلى شيء فحاجتك مقدمة، حاجتك أنت مقدمة من كسوتك وحاجاتك الأخرى أنت مقدمة، وما فضل عن حاجتك له التصرف فيه في حاجته هو. أما أن يعطيه أولاده الآخرين ليبنوا بيوتًا أو لغير ذلك من المقاصد الأخرى فلا. أما النفقة التي فرض الله عليه أن ينفقها عليهم فهذا لا بأس أن يتصرف فيما يأخذه منك ومن غيرك في الإنفاق على الآخرين القاصرين الذين هم في حاجة إلى أبيهم وإلى نفقة أبيهم، وإذا سمحت بالمرتب كله يتصرف فيه كيف يشاء فلا حرج في ذلك والحمد لله. نعم. المقدم: جزاكم الله خيرًا. سماحة الشيخ! بعض الآباء يعتقد أن حديث رسول الله ﷺ: أنت ومالك لأبيك يعتقد أن هذا الحديث مطلق وليس له أي قيد، هل توجهون الآباء بشيء في هذه المناسبة؟ الشيخ: مثلما تقدم عند أهل العلم مقيد بعدم الضرر لقوله ﷺ: لا ضرر ولا ضرار والقاعدة الشرعية: أنه لا ضرر أحد لأحد، فلا يضر هذا الولد للولد الثاني، ولا يضر هذه البنت للبنت الثانية، ولكن يأخذ من مالهم ما يحتاجه هو ولا يضرهم، فلو كانت البنت عندها أولاد صغار ما لهم من يقوم عليهم ليس له أن يأخذ من مالها ما يضرها ويضر أولادها هم أولى، وهكذا إذا كانت تحتاج إلى ملابس وإلى كتب تنفعها في دروسها وإلى أشياء نحو ذلك فلابد أن يدع لها ما يقضي حاجتها لا يأخذ منها كل شيء، والقاعدة: لا ضرر ولا ضرار، فلابد أن يدع لها ما يسد حاجتها ويأخذ الفاضل لحاجته. وهكذا لو كان ذكرًا يترك له ولأولاده وزوجته ما يكفيهم ويأخذ من الزائد الفضل، لقوله ﷺ: لا ضرر ولا ضرار  قاعدة شرعية لا يضار أحد بأحد، لابد من عدم الضرر. نعم. المقدم: جزاكم الله خيرًا، فيما إذا أرادت هذه السائلة أن تتزوج أو تبني مسجدًا أو تتصدق كيف تتصرف مع والدها؟ الشيخ: حق والدها مقدم على المسجد وعلى غير المسجد. المقدم: حق والدها؟ الشيخ: ولدها مقدم. المقدم: لكن إذا كان الوالد مستغنيًا مثلًا؟ الشيخ: له أن يأخذ، ما زاد عن حاجتها له أن يأخذ، فبره مقدم على بناء المسجد، بره مقدم، أما حاجتها هي في ملابسها وأكلها وطعامها وأولادها مقدم، تقدم حاجتها هي وأولادها على الوالد، لكن ما فضل عن حاجتها وحاجة أولادها مثلًا له أن يأخذ ما يصرفه في حاجاته. نعم. المقدم: جزاكم الله خيرًا. الشيخ: جمعًا بين الأحاديث. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17052/حكم-اخذ-الاب-مرتب-ابنته-واعطاىه-لابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85005.mp3","categories":["النفقات","بر الوالدين"]},{"id":18145,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (ع. م. أ. الكناني ) من القنفذة.أخونا رسالته مطولة في الواقع ملخصها سماحة الشيخ: أن والده بدأ ينازعه على راتبه، وهو أب لأسرة تتكون من أربعة أشخاص، ويقول: إنه دفع نصف المرتب لوالده، إلا أن الوالد لم يرتض بذلك؛ نظرًا لأن الوالد نفسه يعول أسرة كبيرة فيها تسعة أنفس ويرجو من سماحة الشيخ التوجيه؟ جزاكم الله خيرًا.","title":"توجيه لمن يطالبه أبوه بالتنازل عن جميع راتبه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دل كتاب الله العزيز وسنة رسوله الأمين عليه الصلاة والسلام على عظم شأن الوالدين وعلى عظم حقهما وعلى وجوب برهما، فالواجب على الولد أن يحرص على بر الوالدين، وأن يخصهما بمزيد عناية؛ لأن الله  يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] الآية، وفي معناها آيات أخرى، وقال جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]، وقال النبي عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم، وجاءه رجل يشتكي أن أباه اجتاح ماله، فقال: أنت ومالك لأبيك. فالواجب عليك أن تتحرى ما يرضي والدك، وأن تحرص على إقناعه بالأسلوب الحسن والعبارات اللطيفة، فتدع لولدك وأهل بيتك ما يكفيهم، وتعطيه ما يعينه على نفقة عائلته، وبذلك يحصل لك الأجر العظيم وبر والدك. أما إن كان النصف الذي يبقى لك لا يكفي حاجتك أو لا يزيد عن حاجتك فلا يلزمك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقد دل على هذا قوله ﷺ: لا ضرر ولا ضرار، حق الوالدين عظيم، ولكن لا ضرر ولا ضرار إذا كان الباقي من راتبك بقدر حاجتك من دون إسراف ولا تبذير، فلا يلزمك أن تعطيه الزيادة، لكن تعتذر إليه بالعبارات الحسنة وبالأساليب الطيبة، أو توسط بعض أقاربك حتى يعتذروا عنك وحتى يرضوه عنك، هذا هو الذي ينبغي لك في هذه المسألة. أما إن كان عندك قدرة على الزيادة وأن تخفض النصف وتعطيه زيادة على النصف وأن هذا يكفيك ويكفي من تحت يدك، حاجة متوسطة ليس فيها إسراف ولا تبذير فافعل ذلك. والخلاصة: أنك تجتهد في إرضاء والدك، لكن من دون ضرر عليك، وعلى أهل بيتك؛ لأن عليك حقًا لزوجتك وأهل بيتك أولادك، وعليك حق لوالدك، فإذا جاء الضرر قدمت حاجة نفسك وحاجة ولدك، وليس لوالدك إلا ما فضل وزاد على هذا، لما تقدم من قوله ﷺ: لا ضرر ولا ضرار، ولقوله ﷺ: ابدأ بنفسك ثم من تعول، فأنت تبدأ بنفسك وأبوك ممن تعول، فتبدأ بنفسك وأهل بيتك، ثم تعطي والدك ما زاد مما يسد حاجته ويعينه على نفقة عياله، يسر الله أمرك وأعانك وبارك لك وعليك وأغنى والدك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17187/توجيه-لمن-يطالبه-ابوه-بالتنازل-عن-جميع-راتبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_853/nour_85301.mp3","categories":["النفقات","بر الوالدين"]},{"id":18823,"question":"من القطيف في المنطقة الشرقية، هذه رسالة وصلت إلى البرنامج من المستمع (م. ر. د) أخونا بدأ رسالته بقوله:بسم الله الرحمن الرحيم. أنا مدرس مصري أعمل بالمنطقة الشرقية، ومدين لبرنامجكم الخالد: نور على الدرب؛ وإذ نشكركم ونتوجه بالدعاء للقائمين عليه، وممن خلف البرنامج ولعلمائنا الأفاضل، جعلكم وجعلهم الله ذخرًا لنا في ديننا ودنيانا. السؤال الأول هو: أنا مقيم بالمملكة بصحبة أسرتي المكونة من زوجتي وولدين، أما والدي الذي يعيش في مصر فتقدم به العمر، ولكنه ما زال يشتغل بالتجارة في محله البسيط، ساعيًا على أخي الذي أنهى دراسته هذا العام، والتحق بالخدمة العسكرية، وعلى أخواتي البنات الاثنتين، ولكن والدي يربطان رضاهم علي بمساعدة أخي المادية، وتحملي نفقة زواجه، وحتى قبل أخواتي البنات، ومن أجل ذلك قطعوا اتصالهم بي، واعتبروني عاقًا لهما، رغم أنني مريض بمرض مزمن، وكم أخشى من المجهول على مصير أولادي وأخشى ما أخشاه، وما يؤرقني عدم رضا الوالدين علي. فأرجو من سماحتكم تبصيري كيف أتصرف تجاه ما يطلب مني الوالدان؟جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في أمرهما بالنفقة على الإخوان","answer":"الجواب: الواجب عليك أن تتقي الله ما استطعت؛ فإن استطعت أن تصل والديك وترضيهما فافعل بما يسر الله لك، بعد حاجتك وحاجة أولادك وزوجتك، فإن لم يتيسر فأنت معذور، واعتذر إليهما بذلك، فإن النفقة عليك وعلى أولادك مقدمة، فعليك أن تنظر في الأمر، وأن تجتهد وتحرص على إرضاء والديك بما يسر الله لك من المال، حتى يرضيا عنك، وحتى تساعد أخاك وأنت على خير عظيم، ولو خففت النفقة على نفسك وأهلك بعض التخفيف الذي لا يضر الجميع لإرضاء والديك، فهذا أمر مطلوب، فاجتهد في الاقتصاد والحرص على أن توفر شيئًا ترضي به والديك، جزاك الله خيرًا. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17955/حكم-طاعة-الوالدين-في-امرهما-بالنفقة-على-الاخوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92107.mp3","categories":["النفقات","بر الوالدين"]},{"id":19150,"question":"في سؤالها الثاني تقول: هل يعتبر إنفاقي على ولدي ثوابًا يغنيني عن إخراج زكاة أموالي؟","title":"حكم إنفاق المرأة على ولدها واحتساب ذلك من الزكاة","answer":"الجواب: لا، الإنفاق على الولد أمر لازم، إذا كان الولد فقيرًا وليس له أب ينفق عليه، إما ميت وإما عاجز، فالنفقة منك عليه واجبة على الصحيح، إذا كنت قادرة، والزكاة لا تصلح للولد، ولا للأب ولا للأم، وإنما تصلح للفقراء من الإخوة والأخوات والأعمام والعمات ونحو ذلك، أما ولدك فالواجب عليك الإنفاق عليه من مالك، أما الزكاة فتنفق في جهات أخرى، الزكاة تنفق في أهلها من الفقراء والمساكين غير أولادك. نعم.","link":"https://binbaz.org.sa/fatwas/18326/حكم-انفاق-المراة-على-ولدها-واحتساب-ذلك-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88602.mp3","categories":["النفقات","الآداب والأخلاق المحمودة"]},{"id":19657,"question":"تقول هذه السائلة يا سماحة الشيخ، امرأة كانت تأخذ من المصروف الذي خصصه لها زوجها، فتشتري حاجات مباحة لأناس لا يرغب فيهم هذا الزوج، ثم حصل الفراق بينها وبينه وهي نادمة الآن، فهل عليها إثم؟ وكيف الخلاص من ذلك إن كان ذنبًا؟","title":"حكم أخذ الزوجة من مال زوجها بغير إذنه","answer":"الجواب: ليس لها ذلك، ليس لها أن تخرج من ماله إلا بإذنه، ما دام نهاها أن تعطيهم ليس لها أن تعطيهم إلا بإذنه إلا من مالها، فإذا طلقها وهي تعرف ما أخرجت، فالأحوط لها أن ترده عليه أو تستأذنه أو تستبيحه تقول له: إني فعلت كذا سامحني، أو ترد عليه ما أخذت. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18941/حكم-اخذ-الزوجة-من-مال-زوجها-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95011.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]}]
